(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c54"]=[{"id":"00015194","register_sub_id":"101","register_pk":"530618","name":"旧鈴木家住宅弓道場矢場","kana":"きゅうすずきけじゅうたくきゅうどうじょうやば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県浜松市中央区中郡町字万斛西980","lat":34.773425,"lng":137.77429167,"geo_status":"db","era":"昭和6年頃／令和5年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺及び鉄板葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"22 - 0335","desc":"旧家の屋敷に由来する公園内に残る弓道場の矢場。的場と相対して建つ切妻造桟瓦葺東西棟で、鉄板葺の下屋を廻らせる。内部は天井を高く張った射場を中心に、南・東を畳敷の小上がりとし、控席、審判席を配す。審判席東面には床を構えて格式を備えた矢場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015194"},{"id":"00014158","register_sub_id":"101","register_pk":"508788","name":"旧須藤家熱海別邸（須藤水園）主屋","kana":"きゅうすどうけあたみべってい（すとうすいえん）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県熱海市春日町77-3","lat":35.10162222,"lng":139.07891111,"geo_status":"db","era":"昭和前期／令和2年改築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積197㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"22-0315","desc":"ＪＲ熱海駅南側、相模湾を望む高台に建つ。海への眺望に配慮したほぼ東西棟の木造二階建で、玄関脇に洋室、南東隅に湯屋を配す。正面は入母屋破風を三つ並べる重厚な構えで、内部は良材を用いた端正なつくりとする。鉄道駅開業当時の熱海の別荘地開発の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014158"},{"id":"00014610","register_sub_id":"101","register_pk":"515152","name":"旧津倉家住宅応接棟","kana":"きゅうつくらけじゅうたくおうせつとう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県磐田市掛塚1099-1","lat":34.67360833,"lng":137.79705833,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"22 - 0320","desc":"掛塚湊で廻船や材木で繁栄した旧家の洋風応接棟。主屋の土間に接続して通り沿いに並ぶ。緩勾配の切妻造鉄板葺の平屋建、軸部材は縦長断面で統一し、南面テラス化粧梁を室内に引き込む。内部はマントルピースを置く一室。大理石風のテラス石造列柱が目を惹く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014610"},{"id":"00014609","register_sub_id":"101","register_pk":"515151","name":"旧津倉家住宅主屋","kana":"きゅうつくらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県磐田市掛塚1099-1","lat":34.67368333,"lng":137.79697222,"geo_status":"db","era":"明治22年","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造2階建、瓦葺、建築面積189㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"22 - 0319","desc":"掛塚湊の廻船問屋と材木商で繁栄した旧家の主屋。寄棟造妻入桟瓦葺、通りに格子を構えた二階建。主体部は通り土間とミセや内向き部屋からなり、その西に座敷を角屋で設ける。材木商らしく材に凝った造りで座敷の壁一枚板は見所。水運が繁栄した時代を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014609"},{"id":"00014611","register_sub_id":"101","register_pk":"515153","name":"旧津倉家住宅土蔵","kana":"きゅうつくらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県磐田市掛塚1099-1","lat":34.67391389,"lng":137.79691667,"geo_status":"db","era":"明治22年頃／昭和20年頃改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造2階建、瓦葺、建築面積26㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"22 - 0321","desc":"掛塚湊の廻船問屋と材木商で繁栄した旧家の土蔵。切妻造平入桟瓦葺、伊豆石貼の二階建土蔵。切石三段積で床高く天竜川の水害に備え、片引土戸を建てて内部は各階板敷、内壁漆喰仕上、小屋組は船材を転用した地棟に登梁形式。水運業と伊豆石の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014611"},{"id":"00014388","register_sub_id":"101","register_pk":"511377","name":"旧テーテンス熱海別邸（稲村ハウス）主屋","kana":"きゅうてーてんすあたみべってい（いなむらはうす）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県熱海市伊豆山字稲村353-4","lat":35.11918056,"lng":139.09793611,"geo_status":"db","era":"昭和17年頃","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積116㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"22 - 0316","desc":"熱海市伊豆山の海沿いの崖上に建つ別荘。設計は前川國男建築設計事務所。く字形平面の木造平屋建で、外装下見板張。居間の海側開口部は天井まで全面ガラス戸とし、玄関ホールの石積・石敷、磨き丸太の独立柱と一体化した戸棚等にモダニズム建築の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014388"},{"id":"00013119","register_sub_id":"101","register_pk":"368276","name":"旧東郷家別邸（伊東東郷記念館）","kana":"きゅうとうごうけべってい（いとうとうごうきねんかん）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県伊東市渚町58-1","lat":34.97101111,"lng":139.10013889,"geo_status":"db","era":"昭和4年／昭和7年増築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺及び金属板葺、建築面積169㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"22 － 0284","desc":"かつて海を望んだ敷地に東郷平八郎が営んだ別邸。竣工三年後に離れを増築した。北に玄関を構える木造平屋建で、南東の庭に面して座敷を配し、下屋の縁を廻らす。座敷飾にカエデなどの銘木を使い端正な意匠でまとめる。保養地伊東の戦前の別邸として希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013119"},{"id":"00015199","register_sub_id":"101","register_pk":"530623","name":"旧永田家住宅（高野屋）石垣及び石塀","kana":"きゅうながたけじゅうたく（こうのや）いしがきおよびいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県賀茂郡南伊豆町上小野字八重金谷戸348","lat":34.66833889,"lng":138.82478333,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造、総延長123m、石段付","structure_material":"石造","registered":"2024.12.03(令和6.12.03)","register_no":"22 - 0340","desc":"敷地外周を囲繞し、長屋門に取付く石垣及び石塀と、敷地正面と長屋門脇の石塀及び石段。伊豆石を用い、北面石垣は高さ三メートル弱の野面積とする。石塀は精緻な切石の谷積や布積で頂部に笠石を伏せて整える。地域色豊かで旧家の風格ある屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015199"},{"id":"00015196","register_sub_id":"101","register_pk":"530620","name":"旧永田家住宅（高野屋）主屋","kana":"きゅうながたけじゅうたく（こうのや）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県賀茂郡南伊豆町上小野字八重金谷戸348","lat":34.66836389,"lng":138.824575,"geo_status":"db","era":"明治中期／平成10年代改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積156㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"22 - 0337","desc":"伊豆半島南端の山間に所在。敷地北寄りに南面する平屋建寄棟造桟瓦葺で四方に下屋を廻らし外壁全面を海鼠壁、軒を漆喰塗込とする。平面は南西隅を土間とし前後二列に分け、前列に座敷を並べ南東に縁を通す。海鼠壁を多用した外観に顕著な地方的特色を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015196"},{"id":"00015197","register_sub_id":"101","register_pk":"530621","name":"旧永田家住宅（高野屋）蔵","kana":"きゅうながたけじゅうたく（こうのや）くら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県賀茂郡南伊豆町上小野字八重金谷戸348","lat":34.66836389,"lng":138.82439444,"geo_status":"db","era":"明治中期／平成10年代改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積47㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"22 - 0338","desc":"主屋の西に建つ南北棟の米蔵兼家財蔵。土蔵造二階建、切妻造桟瓦葺で東面に蔵前を設けて戸口とする。伊豆石の切石積基礎上に建ち、破風を含めた外壁のみならず蔵前内部まで海鼠壁とする重厚なつくり。見応えある上質な土蔵で主屋と一体的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015197"},{"id":"00015198","register_sub_id":"101","register_pk":"530622","name":"旧永田家住宅（高野屋）長屋門","kana":"きゅうながたけじゅうたく（こうのや）ながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県賀茂郡南伊豆町上小野字八重金谷戸348","lat":34.66826389,"lng":138.82438889,"geo_status":"db","era":"明治中期／平成10年代改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺及び鉄板葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"22 - 0339","desc":"敷地西面南寄りに南北棟で建つ長屋門。寄棟造平入桟瓦葺で、東面に鉄板葺の下屋を付す。外壁を漆喰塗とし腰高に簓子下見板を張る。中央を石敷通路として門口を開き、南北に部屋を設ける。通路南側の小部屋はもと牛小屋と伝わる。旧家の表構えをつくる長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015198"},{"id":"00007357","register_sub_id":"101","register_pk":"108339","name":"旧南葵文庫","kana":"きゅうなんきぶんこ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県熱海市伊豆山字東谷758-1-1他","lat":35.112785,"lng":139.087524,"geo_status":"db","era":"明治32／昭和8移築・昭和62移築改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、銅板葺、建築面積151㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"22 － 0133","desc":"相模湾に臨む丘の斜面に南面して建つ。桁行１５ｍ梁間１１ｍ、木造２階建で、寄棟造妻入とし、東面にはサンルームを張り出す。フリーズに和風を加味した植物文様をあしらいながらも、全体としてはルネサンス様式を基調とした端正なデザインでまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007357"},{"id":"00015024","register_sub_id":"101","register_pk":"529302","name":"旧新津家別邸表門","kana":"きゅうにいつけべっていおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆の国市奈古谷字浜井場740-1","lat":35.07883889,"lng":138.96973611,"geo_status":"db","era":"昭和12年／昭和後期頃改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、瓦葺一部銅板葺、間口2.0m、袖塀付","structure_material":"木造","registered":"2024.08.15(令和6.08.15)","register_no":"22 - 0334","desc":"敷地西辺に開く間口一間の門で、左右に袖塀を付す。寄棟屋根の上半を一文字瓦葺、下半を銅板葺とする。化粧の棟木、桁を丸太とし流板張の軒を深めに出しつつ軽快にみせる。門口の扉は細竹を詰打ちする瀟洒なつくり。自由かつ繊細な意匠で整えた気品ある表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015024"},{"id":"00015022","register_sub_id":"101","register_pk":"529300","name":"旧新津家別邸主屋","kana":"きゅうにいつけべっていおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆の国市奈古谷字浜井場740-1","lat":35.07871111,"lng":138.96988333,"geo_status":"db","era":"昭和12年／昭和後期・平成29年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積344㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"22 - 0332","desc":"畑毛温泉にある石油商の別邸主屋。南面する二階建居間棟の東に玄関棟、西に家政棟を雁行。全体和風基調で居間棟は各階和室の縁にガラス戸を建てる。玄関棟のサンルームは天井にアールデコ調ステンドグラスを飾るなど和洋の意匠を巧みに用いた優美な別荘建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015022"},{"id":"00015023","register_sub_id":"101","register_pk":"529301","name":"旧新津家別邸土蔵","kana":"きゅうにいつけべっていどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆の国市奈古谷字浜井場740-1","lat":35.07864167,"lng":138.96959167,"geo_status":"db","era":"昭和12年／令和3年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"22 - 0333","desc":"主屋の西に建つ家財蔵。土蔵造二階建切妻造、置屋根形式の桟瓦葺。北妻を戸口として鉄扉を開き下屋を設けて蔵前とする。外壁は漆喰塗仕上で軒に鉢巻を廻らし、腰を海鼠壁とする。両妻に庇付の窓を開き、北妻に家紋を飾る。別邸の敷地景観を整える重厚な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015023"},{"id":"00013398","register_sub_id":"101","register_pk":"368483","name":"旧深澤家住宅主屋（古民家割烹ひよけ家）","kana":"きゅうふかざわけじゅうたくおもや（こみんかかっぽうひよけや）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊東市宇佐美字城宿1748-1","lat":35.006925,"lng":139.08423611,"geo_status":"db","era":"昭和6年／平成30年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積82㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"22 － 0286","desc":"海岸沿いの旧道に東面する二階建の町家。一階前面を下屋とし、北寄りに出入口を設け、他は格子とする。相模灘を望む二階はほぼ全面をガラス窓として庇と高欄を付す。上下階とも欄間や下地窓などに瀟洒な意匠を施す。宇佐美地区で希少な戦前の和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013398"},{"id":"00000410","register_sub_id":"101","register_pk":"101400","name":"旧マッケンジー住宅","kana":"きゅうまっけんじーじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県静岡市駿河区高松2852","lat":34.94562783,"lng":138.41942258,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造地上2階地下1階建塔屋付，瓦葺，建築面積283㎡","structure_material":"木造地上2階地下1階建塔屋付","registered":"1997.12.12(平成9.12.12)","register_no":"22 － 0007","desc":"日本茶の輸出に貢献し，各種社会事業にも尽くしたマッケンジー夫妻の旧宅。伊豆半島を望む駿河湾岸の広大な敷地に建つ。W.M.ヴォーリスの設計で，木造２階建，望楼付のスパニッシュスタイルになる。赤瓦屋根とモルタル塗りの白壁の対比がひときわ目立つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000410"},{"id":"00011961","register_sub_id":"101","register_pk":"354924","name":"旧六所家門及び塀","kana":"きゅうろくしょけもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県富士市今泉八丁目1428-1他","lat":35.166254,"lng":138.686794,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"門 木造、瓦葺、間口6.7m 塀 木造、瓦葺、総延長43m","structure_material":"門 木造","registered":"2017.10.27(平成29.10.27)","register_no":"22-243","desc":"敷地南面中央の石段上に構える門と左右にのびる塀。門は三間薬医門、切妻造桟瓦葺で正面を出桁とする。中央間を板戸両開として西間に潜戸を設け、壁は漆喰塗で腰高に簓子下見板を張る。塀は石垣上に建ち、竪板張。間口の広い薬医門が地域の歴史を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011961"},{"id":"00010972","register_sub_id":"101","register_pk":"208942","name":"小長井家住宅奥蔵","kana":"こながいけじゅうたくおくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県静岡市葵区土太夫町22-1他","lat":34.977935,"lng":138.373504,"geo_status":"db","era":"明治39／昭和中期移築","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積25㎡","structure_material":"土蔵造3階建","registered":"2016.02.25(平成28.02.25)","register_no":"22-0216","desc":"敷地の南奥に南北棟で建ち、桁行五・五メートル梁間四・五メートル、木造三階建、切妻造桟瓦葺。木造の軸部に石張したうえで漆喰塗で仕上げ、水切と軒蛇腹を廻らす。一階両妻を戸口とし、二階窓に重厚な土戸を開く。店蔵とともに茶問屋の屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010972"},{"id":"00010971","register_sub_id":"101","register_pk":"208941","name":"小長井家住宅店蔵","kana":"こながいけじゅうたくみせぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県静岡市葵区土太夫町22-1他","lat":34.978068,"lng":138.373581,"geo_status":"db","era":"大正8／昭和中期移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"22-0215","desc":"事務所の裏に南北棟で建ち、桁行四・五メートル梁間三・六メートル、木造二階建、切妻造桟瓦葺。木造の軸部に石張し、漆喰塗で仕上げて軒蛇腹を廻らす。一階北面を戸口とし南妻の窓ともに丁寧な漆喰仕上げの土戸を開く。市街地に残る特異な工法の蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010971"},{"id":"00011703","register_sub_id":"101","register_pk":"210719","name":"三養荘（旧岩崎久彌別邸）本館居間・書斎棟","kana":"さんようそう（きゅういわさきひさやべってい）ほんかんいま・しょさいとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県伊豆の国市墹之上字谷戸洞270-1他","lat":35.039626,"lng":138.933174,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、スレート葺一部銅板葺、建築面積141㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"22-0236","desc":"中央棟の北東隅から雁行状に北東に伸びる平屋建、入母屋造人造スレート葺で、北東南の三方に畳縁を廻らし一〇畳座敷と八畳次の間を設け、その北東に前室を介して八畳座敷を配す。一〇畳長手方向に松一枚の蹴込床とするなど、本館の中でも最も上質な空間をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011703"},{"id":"00011704","register_sub_id":"101","register_pk":"210720","name":"三養荘（旧岩崎久彌別邸）本館客間棟","kana":"さんようそう（きゅういわさきひさやべってい）ほんかんきゃくまとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県伊豆の国市墹之上字谷戸洞270-1他","lat":35.039363,"lng":138.933302,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、スレート葺一部銅板葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"22-0237","desc":"玄関・茶室棟の東に続く入母屋造、人造スレート葺の平屋建。本館の中で、表向きの接客空間をなす建物で、南北棟に一二畳座敷と一〇畳次の間を配し、北・東・南の三方に縁を廻らし、ガラス戸を建てる。廊下を舟底天井とするなど、数奇屋風意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011704"},{"id":"00011705","register_sub_id":"101","register_pk":"210721","name":"三養荘（旧岩崎久彌別邸）本館玄関・茶室棟","kana":"さんようそう（きゅういわさきひさやべってい）ほんかんげんかん・ちゃしつとう","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆の国市墹之上字谷戸洞270-1他","lat":35.039337,"lng":138.933111,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、スレート葺一部銅板葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"22-0238","desc":"岩崎久彌の別邸として建てられたもの。本館玄関・茶室棟は本館の南寄りに建つ入母屋造、人造スレート葺の平屋建。玄関を入って右には応接室、左には事務室を置き、左奥には四畳半台目で比較的形式にとらわれない茶室を設ける。質の高い近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011705"},{"id":"00011702","register_sub_id":"101","register_pk":"210718","name":"三養荘（旧岩崎久彌別邸）本館中央棟","kana":"さんようそう（きゅういわさきひさやべってい）ほんかんちゅうおうとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県伊豆の国市墹之上字谷戸洞270-1他","lat":35.039534,"lng":138.933063,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、スレート葺一部銅板葺、建築面積214㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"22-0235","desc":"岩崎久彌の別邸として建てられたもの。東下りの緩斜面に東面して建つ。入母屋造人造スレート葺、二階建で、八畳座敷と次の間を配し、二階は階段を挟んで三室を設ける。奥の平屋建には一〇畳座敷と次の間を設ける。意匠・造作共に質の高い大規模近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011702"},{"id":"00011707","register_sub_id":"101","register_pk":"210723","name":"三養荘（旧岩崎久彌別邸）本館待合","kana":"さんようそう（きゅういわさきひさやべってい）ほんかんまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県伊豆の国市墹之上字谷戸洞270-1他","lat":35.039443,"lng":138.93367,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、杉皮葺、建築面積4.2㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"22-0240","desc":"客間棟の東、庭の南端に本館と対面して建つ腰掛待合。北面を吹放ちとし、南面は壁、東面には中敷居窓、西面には下地窓を入れた土壁とする。室内南と西には腰掛を設け、土間床は洗い出し、屋根は寄棟造杉皮葺。小規模ながら意匠を凝らした待合である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011707"},{"id":"00011708","register_sub_id":"101","register_pk":"210724","name":"三養荘（旧岩崎久彌別邸）本館露地門","kana":"さんようそう（きゅういわさきひさやべってい）ほんかんろじもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆の国市墹之上字谷戸洞270-1他","lat":35.039409,"lng":138.933175,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、こけら葺、間口1.2m","structure_material":"木造","registered":"2017.06.28(平成29.06.28)","register_no":"22-0241","desc":"客間棟の北西に建ち、玄関・茶室棟の茶室に至る。間口一・二メートルの小ぶりな腕木門で、扉は木枠に縦桟を入れた両開きとする。柱、桁、垂木などほとんどの部材を雑木を手斧はつり仕上げとし、屋根はこけら葺。簡素ではあるが、軽快な意匠の露地門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011708"},{"id":"00007885","register_sub_id":"101","register_pk":"108865","name":"静岡市立高等学校旧正門","kana":"しずおかしりつこうとうがっこうきゅうせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県静岡市葵区千代田3-36-2","lat":34.99237457,"lng":138.39946302,"geo_status":"db","era":"明治前期／昭和33・昭和58移築・昭和61改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口2.9m、袖塀及び潜り付","structure_material":"木造","registered":"2009.11.02(平成21.11.02)","register_no":"22-0136","desc":"東面して建つ高さ４．７ｍの高麗門。間口２．９ｍに五平柱を建て、鼻先を木鼻風に造る腕木を出し、一軒疎垂木の軒を支持、起りのある切妻造桟瓦葺屋根を掛ける。両開板戸を吊り、上部に竪連子を嵌める。北に潜り、南に袖塀を付ける。規模の大きい高麗門の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007885"},{"id":"00002255","register_sub_id":"101","register_pk":"103245","name":"志田家住宅主屋","kana":"しだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県静岡市清水区蒲原3-19-28","lat":35.11949407,"lng":138.60293852,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積194㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"22 － 0074","desc":"旧東海道に北面し，短冊状の敷地に建つ町屋建築。志田家は，醸造業を営み地主を兼ねた旧家。木造２階建，切妻造，平入で，土間の戸口に大戸の痕跡，道路に面した開口部に蔀戸を残し，蒲原宿の往時の佇まいを今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002255"},{"id":"00012153","register_sub_id":"101","register_pk":"352952","name":"次郎長生家（旧高木家住宅）","kana":"じろちょうせいか（きゅうたかぎけじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"静岡県","address":"静岡県静岡市清水区美濃輪町831-1他","lat":35.005686,"lng":138.490702,"geo_status":"db","era":"江戸末期／昭和35年曳家、平成29年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺一部金属板葺、建築面積106㎡","structure_material":"木造平屋一部2階建","registered":"2018.03.27(平成30.03.27)","register_no":"22-244","desc":"清水次郎長の生家として知られる。チョウナ痕、和釘の使用などから近世に遡ると考えられる。間口二間半で、奥行五間半の平屋とその奥の奥行四間二尺の二階建からなり、正面右に一間幅の土間を背面まで通す。地域の歴史を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012153"},{"id":"00008008","register_sub_id":"101","register_pk":"128839","name":"鈴木家住宅石垣","kana":"すずきけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県静岡市葵区中ノ郷250","lat":35.02994568,"lng":138.36189119,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、延長23m","structure_material":"石造","registered":"2010.01.15(平成22.01.15)","register_no":"22-0144","desc":"主屋背面の敷地内段差に築かれた石垣。最大高２．１ｍ、折曲り延長２３ｍとし、東・西に石段を設け、東端は池泉庭園の石組と一体に積む。緩やかな反りをもたせ、積石の合端を丁寧に加工し、隅部を算木積とするなど、旧家の屋敷に相応しい良質な造りである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008008"},{"id":"00013810","register_sub_id":"101","register_pk":"507772","name":"鈴木家住宅内塀","kana":"すずきけじゅうたくうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和中","pref":"静岡県","address":"静岡県掛川市伊達方字滑川574","lat":34.78555556,"lng":138.06570278,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"木造、瓦葺、延長34m","structure_material":"木造","registered":"2021.06.24(令和3.06.24)","register_no":"22 － 303","desc":"主屋南西の庭を限る塀、主屋北西隅と北土蔵を繋ぐ塀からなる。総延長三四メートル、高さ約二メートル、屋根桟瓦葺 。庭園側の塀は貫を現し、壁は漆喰仕上とし、庭園側に控えをとる。北西の塀は漆喰で仕上げ巾木板を張る。外塀とともに屋敷内の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013810"},{"id":"00013798","register_sub_id":"101","register_pk":"507760","name":"鈴木家住宅主屋","kana":"すずきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県掛川市伊達方字滑川574","lat":34.785575,"lng":138.06586111,"geo_status":"db","era":"江戸末期／昭和37年頃増築、同55年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、銅板葺、建築面積363㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"22 － 0291","desc":"石垣で囲まれた敷地中央に南面して建つ。桁行八間半梁間五間、平屋一部二階建切妻造銅板葺の主体部の正側面に桟瓦葺の下屋を廻らし、北西に入母屋造の突出部を張出す。東は落棟の土間、西は三列七室で正面に広縁を通す。大庄屋の佇まいを伝える豪壮な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013798"},{"id":"00013804","register_sub_id":"101","register_pk":"507766","name":"鈴木家住宅瓦小屋","kana":"すずきけじゅうたくかわらごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県掛川市伊達方字滑川574","lat":34.78538611,"lng":138.06610278,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"22 － 0297","desc":"敷地の東南隅に建つ。桁行四・八メートル、梁間三・六メートルの小規模な小屋で古瓦などを収納する。平屋建切妻造桟瓦葺で妻入とする。内部は土間の一室で、天井を張らず竹野地を現す。南北の妻面には敷地を画する外塀が接続する。屋敷構えを構成する要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013804"},{"id":"00013806","register_sub_id":"101","register_pk":"507768","name":"鈴木家住宅北馬屋","kana":"すずきけじゅうたくきたうまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県掛川市伊達方字滑川568-1","lat":34.78513611,"lng":138.06598889,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"22 － 0299","desc":"旧街道から屋敷地への路地沿いに西面して建つ馬屋。南面には南馬屋が続く。平屋建で切妻造桟瓦葺とする。桁行二三メートル、梁間四・五メートルで北から五つに区分される。腰は竪板を張り、上部は割竹を並べて横から竹を編込むなど、特徴ある景観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013806"},{"id":"00013801","register_sub_id":"101","register_pk":"507763","name":"鈴木家住宅北土蔵","kana":"すずきけじゅうたくきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県掛川市伊達方字滑川574","lat":34.78573889,"lng":138.06568889,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"22 － 0294","desc":"敷地の北西隅に建つ。桁行五間梁間二間で、土蔵造二階建切妻造桟瓦葺とし、南面に下屋を付す。内部は一、二階とも二室に区画。腰を海鼠壁で飾り、妻面及び北面に水切瓦を廻らす。南面開口の土戸は掛子塗とし、二階窓脇に袖壁を設ける等丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013801"},{"id":"00008002","register_sub_id":"101","register_pk":"128834","name":"鈴木家住宅米蔵","kana":"すずきけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県静岡市葵区中ノ郷249","lat":35.02976714,"lng":138.36183813,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造平屋建、瓦葺、建築面積45㎡","structure_material":"煉瓦造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"22-0138","desc":"主屋の西側に建ち、桁行６．９ｍ梁間５．０ｍ、煉瓦造、寄棟造妻入桟瓦葺で、南面の出入口に下屋を付ける。壁体はイギリス積で一枚半厚とし、外部は内法高に水切りをまわす。軒蛇腹は二段に迫り出し、小屋組は和小屋とする。主屋と対照的に堅牢な外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008002"},{"id":"00008001","register_sub_id":"101","register_pk":"128833","name":"鈴木家住宅主屋","kana":"すずきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県静岡市葵区中ノ郷249","lat":35.02982946,"lng":138.36196277,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積265㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"22-0137","desc":"敷地中央に南面して建ち、建築面積２６５㎡、木造平屋建、寄棟造桟瓦葺である。正面中央に構える玄関の東側を洋間の応接間とし、外観も、他が簓子下見板張とするのに対し、応接間は南京下見板張とする。落ち着いた外観の、和洋併立近代住宅の一つである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008001"},{"id":"00013809","register_sub_id":"101","register_pk":"507771","name":"鈴木家住宅外塀","kana":"すずきけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県掛川市伊達方字滑川574","lat":34.78528611,"lng":138.06576944,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、延長72m","structure_material":"木造","registered":"2021.06.24(令和3.06.24)","register_no":"22 － 0302","desc":"敷地南辺を区切る長屋門東端から瓦小屋、及び長屋門西端から西土蔵間に続く塀、敷地西北角を矩折に区切る塀、敷地東辺北端の塀の合計四棟、総延長七二メートルからなる外塀。いずれも目板瓦葺で、壁を漆喰仕上や竪板張等として変化をつけ、屋敷景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013809"},{"id":"00008007","register_sub_id":"101","register_pk":"128838","name":"鈴木家住宅中庭仕切り塀","kana":"すずきけじゅうたくなかにわしきりべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県静岡市葵区中ノ郷249","lat":35.02970651,"lng":138.36199056,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、銅板葺及び鉄板葺、延長6.7m","structure_material":"木造","registered":"2010.01.15(平成22.01.15)","register_no":"22-0143","desc":"主屋の玄関と応接間の境から南に延びる。延長６．７ｍ、銅板葺及び鉄板葺で、中央に切妻造の門を開く。軸部は土台上に柱を建て、竪板張目板打とする。門は南半間を袖壁として、板戸片引きとする。前庭と中庭を仕切る塀で、落ち着いた屋敷景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008007"},{"id":"00013808","register_sub_id":"101","register_pk":"507770","name":"鈴木家住宅長屋門","kana":"すずきけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県掛川市伊達方字滑川574","lat":34.78532222,"lng":138.06593056,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"22 － 0301","desc":"屋敷地南辺の中央、主屋の南に建つ。桁行七間半梁間二間半で切妻造桟瓦葺。外壁は漆喰塗で腰は板張。中央西寄りに門口を開け、本柱で冠木を受け両開き板戸を吊る。両脇は部屋で西は畳敷に天井を張り、東は土間床に化粧屋根裏。旧家の格式を示す雄大な長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013808"},{"id":"00008006","register_sub_id":"101","register_pk":"128837","name":"鈴木家住宅長屋門","kana":"すずきけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県静岡市葵区中ノ郷249","lat":35.02964925,"lng":138.36200066,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"22-0142","desc":"主屋正面の石垣上に建ち、桁行１８ｍ梁間３．３ｍ、木造平屋建、切妻造桟瓦葺である。中央やや西寄りに門口を開き、西室は床張とし、東室は土間の納屋とする。外部は竪板張で正面に庇付の窓を穿つ。重厚な外観の長屋門で、旧家の屋敷構えを引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008006"},{"id":"00013805","register_sub_id":"101","register_pk":"507767","name":"鈴木家住宅納屋","kana":"すずきけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県掛川市伊達方字滑川574","lat":34.78562778,"lng":138.06603333,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"22 － 0298","desc":"主屋の東、敷地東辺に建つ。東壁は敷地境の塀に接続する。平屋建切妻造桟瓦葺の小規模な納屋。南北二室からなり、西面は柱間を開放とする。小屋組は和小屋。家相図等から、この場所は代々竈や薪が置かれたことから、煮炊場であった。民家の様相を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013805"},{"id":"00013802","register_sub_id":"101","register_pk":"507764","name":"鈴木家住宅西土蔵","kana":"すずきけじゅうたくにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県掛川市伊達方字滑川574","lat":34.78536944,"lng":138.06576389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積84㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"22 － 0295","desc":"敷地の南西隅に建つ。桁行六間梁間三間半で、土蔵造二階建切妻造桟瓦葺の南北棟とする。東面に下屋を付し、板戸片引を二箇所に建てる。漆喰で鉢巻まで塗込め、妻面には水切瓦を三段に飾り、腰は簓子下見板張とする。南妻に窓を二連並べ、景観を特色づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013802"},{"id":"00013799","register_sub_id":"101","register_pk":"507761","name":"鈴木家住宅西長屋","kana":"すずきけじゅうたくにしながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県掛川市伊達方字滑川574","lat":34.78574722,"lng":138.06583889,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積54㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"22 － 0292","desc":"敷地北端に高石垣際に東長屋と並び建つ。桁行五間半梁間二間半、東西棟の二階建切妻造桟瓦葺で、南面に下屋を設ける。内部は中央に階段、東西に和室を配する。二階の曲面の天井や座敷飾り等に数寄屋意匠を採用。東端に出入口を開け、裏門の機能を併せ持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013799"},{"id":"00013803","register_sub_id":"101","register_pk":"507765","name":"鈴木家住宅東土蔵","kana":"すずきけじゅうたくひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県掛川市伊達方字滑川574","lat":34.78538611,"lng":138.06602778,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"22 － 0296","desc":"主屋の東南、敷地の東南に棟をやや東に振って建つ。桁行三間半梁間二間、土蔵造二階建切妻造桟瓦葺のやや小振りな蔵で西面に下屋を付し戸口を設ける。妻面を水切瓦で飾り、漆喰で鉢巻まで塗込め腰を簓子下見板とする。南妻面の水切瓦と窓が景観を特色づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013803"},{"id":"00013800","register_sub_id":"101","register_pk":"507762","name":"鈴木家住宅東長屋","kana":"すずきけじゅうたくひがしながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県掛川市伊達方字滑川574","lat":34.78575833,"lng":138.06594722,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積51㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"22 － 0293","desc":"敷地北端の高石垣際に西長屋と並び建つ。桁行五間梁間三間、東西棟の二階建切妻造桟瓦葺で、南面に下屋を設ける。内部は一、二階とも二室で、居室ではなく物置として使用。二階北面には窓を開く。小屋は登梁形式。西長屋とともに屋敷北辺の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013800"},{"id":"00008003","register_sub_id":"101","register_pk":"128835","name":"鈴木家住宅文蔵","kana":"すずきけじゅうたくふみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県静岡市葵区中ノ郷250","lat":35.03004252,"lng":138.36193835,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"22-0139","desc":"主屋後方の石垣上に建つ。桁行５．５ｍ梁間３．６ｍ、土蔵造２階建、切妻造妻入桟瓦葺で、四周に下屋庇を巡らせる。１階は正・背面を出入口とし、２階も正・背面に庇付の窓を設ける。正面外壁を海鼠壁として、２階に水切りを付ける、丁寧な造りの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008003"},{"id":"00008004","register_sub_id":"101","register_pk":"128836","name":"鈴木家住宅味噌倉","kana":"すずきけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県静岡市葵区中ノ郷250","lat":35.03004084,"lng":138.36201582,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"22-0140","desc":"主屋後方の石垣上、文蔵の東隣に建つ。桁行２．７ｍ梁間３．０ｍ、木造平屋建、切妻造桟瓦葺で、正面を葺き降ろしの下屋とする。外壁は竪板張目板打で、南正面東半を板戸片引きの出入口とする。文蔵と対照的に簡素な外観の倉で、屋敷構えの一郭を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008004"},{"id":"00013807","register_sub_id":"101","register_pk":"507769","name":"鈴木家住宅南馬屋","kana":"すずきけじゅうたくみなみうまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県掛川市伊達方字滑川568-1","lat":34.78498889,"lng":138.06598889,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"22 － 0300","desc":"旧街道から屋敷地への路地沿いに西面して建つ馬屋。北馬屋の南面に続く。平屋建で切妻造桟瓦葺とする。桁行七・三メートル、梁間四・〇メートルと北馬屋より小規模で、内部は土間の一室である。北馬屋同様割竹を並べ横から竹を編込む等、特徴ある景観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013807"},{"id":"00008005","register_sub_id":"101","register_pk":"134288","name":"鈴木家住宅渡り廊下","kana":"すずきけじゅうたくわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県静岡市葵区中ノ郷249他","lat":35.02994736,"lng":138.36194593,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"22-0141","desc":"主屋と文蔵の間にあって、石垣の上・下段に建つ廊下と、両者を繋ぐ階段からなる。建築面積１２㎡、木造平屋建、両下造鉄板葺である。手摺の下方を竪板張目板打とし、上方は吹放ちとする。開放的で軽快な造りの階段付廊下で、屋敷構成に変化を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008005"},{"id":"00012155","register_sub_id":"101","register_pk":"352954","name":"高林家住宅田舎家","kana":"たかばやしけじゅうたくいなかや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県浜松市東区有玉南町字宮廻1646-1","lat":34.751503,"lng":137.751979,"geo_status":"db","era":"昭和6年／昭和前期曳家、昭和60年代改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、茅葺（銅板仮葺）、建築面積82㎡、渡廊下付","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"22-246","desc":"主屋の南に渡廊下を介して東西棟で建つ。南側の八畳二室の他、小部屋、土間を配する。主室は床を備え長押を廻すのに対し、次室は竹天井や手斧はつりの梁組を現すなど野趣に富む。昭和初期の古民家活用の好例で我が国最初の常設民芸展示場としても価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012155"},{"id":"00014022","register_sub_id":"101","register_pk":"508282","name":"高林家住宅内塀","kana":"たかばやしけじゅうたくうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県浜松市東区有玉南町字宮廻1646-3","lat":34.75159444,"lng":137.75211667,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、瓦葺、延長38m","structure_material":"鉄筋コンクリート造","registered":"2021.10.14(令和3.10.14)","register_no":"22 - 0311","desc":"主屋の玄関東脇から庭を囲む塀で、主屋のサンルームから見た庭の背景となる。一四代当主高林兵衛自ら考案したと伝わる山型に折れた桟瓦を葺き、コンクリート柱の板塀として全体に黒色塗りとする。特色ある意匠で、民藝運動に繋がる意匠の主屋に相応しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014022"},{"id":"00014015","register_sub_id":"101","register_pk":"508275","name":"高林家住宅馬小屋","kana":"たかばやしけじゅうたくうまごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市東区有玉南町字宮廻1646-1","lat":34.75121944,"lng":137.75213889,"geo_status":"db","era":"明治39年頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"22 - 0304","desc":"屋敷林に囲まれた敷地の長屋門の東に西面する南北棟。木造平屋建、切妻造桟瓦葺、壁は中塗仕上で腰はコンクリート基礎を立ち上げ、南面は下見板張。内部を三頭分の馬房に分け、正面に戸を立ててマセ棒を渡す。地域を代表する篤農家の屋敷構えを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014015"},{"id":"00014017","register_sub_id":"101","register_pk":"508277","name":"高林家住宅男衆部屋","kana":"たかばやしけじゅうたくおとこしゅうのへや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市東区有玉南町字宮廻1646-1","lat":34.75143056,"lng":137.75220833,"geo_status":"db","era":"明治39年頃／昭和6年頃改修","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"22 - 0306","desc":"敷地東側に長屋門等の表側区画と主屋の区画の境に建ち、両区画を見渡す男衆部屋の役割が窺える。切妻造桟瓦葺の東西棟で東側に下屋を設け、真壁造中塗仕上に下見板を張る。表側区画に向けて窓を設け、入口は主屋の区画に設けて、屋敷構えの一角を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014017"},{"id":"00012158","register_sub_id":"101","register_pk":"352957","name":"高林家住宅給水塔","kana":"たかばやしけじゅうたくきゅうすいとう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県浜松市東区有玉南町字宮廻1646-1","lat":34.75162,"lng":137.75226,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造、高さ3.7m、建築面積1.5㎡","structure_material":"鉄筋コンクリート造","registered":"2018.03.27(平成30.03.27)","register_no":"22-249","desc":"主屋東側に建つ高さ三・七メートルの鉄筋コンクリート造の給水塔。二五センチメートル角の柱四本を立てて、上部に一・五メートル四方の貯水槽を載せ、モルタル塗で仕上げる。旧家の生活様態を伝える、類例稀な昭和初期の鉄筋コンクリート造の住宅用給水塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012158"},{"id":"00012156","register_sub_id":"101","register_pk":"352955","name":"高林家住宅蔵","kana":"たかばやしけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市東区有玉南町字宮廻1646-3","lat":34.751759,"lng":137.751945,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋一部2階建、瓦葺、建築面積86㎡","structure_material":"木造平屋一部2階建","registered":"2018.03.27(平成30.03.27)","register_no":"22-247","desc":"主屋背面に東西棟で建ち、桁行一二メートル、梁間四・六メートル、切妻造桟瓦葺の蔵の南面に下屋を設け、主屋と渡廊下で接続する。蔵は東西二室で、西室を二階建、東室は上部吹抜けとする。外壁に黒色の簓子下見板を張る、大型で重厚な趣をもつ蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012156"},{"id":"00014019","register_sub_id":"101","register_pk":"508279","name":"高林家住宅地の神社","kana":"たかばやしけじゅうたくじのかみしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市東区有玉南町字宮廻1646-3","lat":34.75180556,"lng":137.75188333,"geo_status":"db","era":"明治39年頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積3.3㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"22 - 0308","desc":"敷地北西角に位置し、南面する小社で外塀が連なる。切妻造桟瓦葺平入、正面に両開き腰板付格子戸を構え、煉瓦積基礎で正面側はモルタル塗。内部は表側を板床、奥側に棚を設け、霊神・宅主神・稲荷神の三社を置く。旧家の屋敷構えに欠くことができない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014019"},{"id":"00012154","register_sub_id":"101","register_pk":"352953","name":"高林家住宅主屋・隠居","kana":"たかばやしけじゅうたくしゅおく・いんきょ","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県浜松市東区有玉南町字宮廻1646-3","lat":34.751653,"lng":137.752008,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"22-245","desc":"主屋は切妻造妻入で妻に曲材の梁と千鳥配置の束を意匠的にみせる。玄関東側はサンルーム付の一二畳、西側は幅広の棚をもつ座敷、その西に隠居を雁行させる。ナグリ仕上の梁を現し、建具に紗綾形、卍崩を用いるなど民芸運動につながる意匠をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012154"},{"id":"00014023","register_sub_id":"101","register_pk":"508283","name":"高林家住宅外塀","kana":"たかばやしけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県浜松市東区有玉南町字宮廻1646-1他","lat":34.75168889,"lng":137.75181667,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造、総延長98m","structure_material":"鉄筋コンクリート造","registered":"2021.10.14(令和3.10.14)","register_no":"22 - 0312","desc":"主屋等の宅地区画を囲んで屋敷林を区切る外塀。鉄筋コンクリート造、モルタル仕上げ、高さ約二メートル、控壁を内側に二メートル間隔で設ける。敷地東側延長五八メートルと、同西側延長四〇メートルから成る。旧家の広大な屋敷構えを形成する重要な工作物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014023"},{"id":"00014016","register_sub_id":"101","register_pk":"508276","name":"高林家住宅堆肥小屋","kana":"たかばやしけじゅうたくたいひごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市東区有玉南町字宮廻1646-1","lat":34.75131111,"lng":137.75215278,"geo_status":"db","era":"明治39年頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"22 - 0305","desc":"敷地南東部の馬小屋北側に並んで建つ堆肥小屋。切妻造桟瓦葺、真壁造中塗仕上で妻に曲り梁を見せる。内部は一室土間で、腰高の切石風コンクリート基礎と、下地窓などの通気口で堆肥小屋としての機能を果たす。馬小屋とともに往時の暮らしぶりを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014016"},{"id":"00012157","register_sub_id":"101","register_pk":"352956","name":"高林家住宅長屋門","kana":"たかばやしけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県浜松市東区有玉南町字宮廻1646-1","lat":34.751232,"lng":137.751999,"geo_status":"db","era":"享和3年(1803)／平成12年改修","year":1803,"year_source":"db","year_min":1803,"year_max":1803,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"22-248","desc":"敷地の南入口に構える寄棟造銅板葺。中央東寄りの門口に板扉を開き、東側に潜戸を設ける。門口の左右を長屋として漆喰壁の南面に与力窓を穿ち、腰は簓子下見板張及び竪板張とする。せがいに勾配をつけており、趣のある屋敷構えをつくる表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012157"},{"id":"00014021","register_sub_id":"101","register_pk":"508281","name":"高林家住宅平門及び塀","kana":"たかばやしけじゅうたくひらもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県浜松市東区有玉南町字宮廻1646-1","lat":34.75141944,"lng":137.75203889,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"平門 木造、瓦葺、間口1.8m 塀 木造、延長26m","structure_material":"平門 木造","registered":"2021.10.14(令和3.10.14)","register_no":"22 - 0310","desc":"田舎屋南東から長屋門の北面に至る南北塀と、表側区画と田舎屋の区画を仕切る平門。門は切妻造桟瓦葺、腕木門で両開き板戸を構える。塀はコンクリート柱の板塀で、長屋門へ折れ曲がった先はひしぎ竹張、内側は杉皮張で意匠を変え、旧家の屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014021"},{"id":"00014020","register_sub_id":"101","register_pk":"508280","name":"高林家住宅平常門及び塀","kana":"たかばやしけじゅうたくへいじょうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県浜松市東区有玉南町字宮廻1646-1","lat":34.75144444,"lng":137.75213333,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"平常門 木造、銅板葺、間口2.7m 塀 木造、延長10m","structure_material":"平常門 木造","registered":"2021.10.14(令和3.10.14)","register_no":"22 - 0309","desc":"男衆部屋西妻から田舎屋南東角に至る東西塀と、表側区画と主屋の区画を仕切る門。昭和初期に主屋と共に建て替えた。門は切妻造、腕木門、出節柱と引分戸を構える。塀はコンクリート柱の板塀で、裏側を杉皮張とする。旧家の奥深い屋敷構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014020"},{"id":"00014018","register_sub_id":"101","register_pk":"508278","name":"高林家住宅味噌倉及び米倉","kana":"たかばやしけじゅうたくみそぐらおよびこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県浜松市東区有玉南町字宮廻1646-1","lat":34.75155278,"lng":137.75224167,"geo_status":"db","era":"明治19年頃／大正頃改修","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"22 - 0307","desc":"敷地東側に位置する南北棟倉庫。切妻造桟瓦葺、壁は真壁造板張で、西に下屋の廊下、東に庇を設けて材木を置く。内部は北から小部屋付味噌倉、塩倉、薪置場に分け、中二階付。一時期米倉、次に織物仕事場に転用しガラス窓を並べる。当家の歴史の変遷を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014018"},{"id":"00000828","register_sub_id":"101","register_pk":"101818","name":"東海道名主の館（小池家住宅）","kana":"とうかいどうなぬしのやかた（こいけけじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県静岡市清水区寺尾464","lat":35.09161422,"lng":138.54856416,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建，瓦葺，建築面積131㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"22 － 0031","desc":"小池家は，江戸時代は代々寺尾村の名主を務めた旧家で，現在の主屋は，由比町の初代助役を務めた先々代が建てたといわれる。切妻造，瓦葺の平屋建住居で，西側を土間とし東側の居室部は田の字型の伝統的な平面を保つ。名主の家として保存公開されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000828"},{"id":"00011143","register_sub_id":"101","register_pk":"205250","name":"東山荘蔵","kana":"とうざんそうくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和中","pref":"静岡県","address":"静岡県熱海市春日町1712-3","lat":35.103977,"lng":139.081614,"geo_status":"db","era":"昭和21","year":1946,"year_source":"db","year_min":1946,"year_max":1946,"year_label":null,"structure":"鉄筋コンクリート造、建築面積19㎡","structure_material":"鉄筋コンクリート造","registered":"2016.08.01(平成28.08.01)","register_no":"22 - 0228","desc":"美術品収蔵用に建てた鉄筋コンクリート造二階建で、茶室北端に接続する。桁行四・九メートル梁間三・九メートル、陸屋根で壁頂にパラペットを廻らせる。外壁漆喰塗で腰の石積風意匠とコーニス風の水切を人造石洗出しで作る。耐火性と意匠性を兼備する収蔵庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011143"},{"id":"00011145","register_sub_id":"101","register_pk":"205252","name":"東山荘正門","kana":"とうざんそうせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県熱海市春日町1712-16","lat":35.10407,"lng":139.081579,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、瓦葺、間口1.8m、南方潜戸付","structure_material":"木造","registered":"2016.08.01(平成28.08.01)","register_no":"22 - 0230","desc":"敷地西辺北端の道路沿いに開く門。総間口三・六メートルの切妻造で、一文字瓦葺の周囲を銅板葺とする。中央間の門口に板戸を引違にたて、北側の半間を土壁として南側に潜戸を開き、両側面も土壁とする。磨丸太で軸部を構成し、端正で気品を備えた意匠の正門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011145"},{"id":"00011142","register_sub_id":"101","register_pk":"205249","name":"東山荘茶室","kana":"とうざんそうちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県熱海市春日町1712-3他","lat":35.103914,"lng":139.081564,"geo_status":"db","era":"昭和15／昭和50頃増築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"22 - 0227","desc":"本館西側のやや高い位置に南北棟で建ち、東側の応接室に縁を設ける。離れと同様、多種の丸太を柱に使い、主室となる大炉之間では、荒加工の梁組と丸竹詰張の天井を現して民家風に見せ、大振りの座敷飾りを備える。主室のほか、六畳や浴室も備えた接客施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011142"},{"id":"00011140","register_sub_id":"101","register_pk":"205247","name":"東山荘離れ","kana":"とうざんそうはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県熱海市春日町1712-4","lat":35.104067,"lng":139.081753,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"22 - 0225","desc":"敷地北端に東西棟で建ち、本館と渡廊下で繋ぐ、一五畳大の応接室と玄関等からなる独立棟。軸部や軒に多様な樹種の丸太を使い、応接室主体部を船底天井、周囲を網代天井などとする数寄屋意匠で上品にまとめつつ、出窓風の長椅子などに当時の住宅の潮流も示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011140"},{"id":"00011141","register_sub_id":"101","register_pk":"205248","name":"東山荘別館","kana":"とうざんそうべっかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県熱海市春日町1712-1","lat":35.103646,"lng":139.08151,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"22 - 0226","desc":"敷地南西隅に位置する木造平屋建で、海側となる東側に座敷を雁行配置し、西に廊下を廻らせる。一三畳の主室では拭板と畳による二畳大の踏込床を残月風に仕立て、北に四半瓦敷の土縁を設ける。数寄屋風意匠と太鼓斫の梁などによる野趣を備え、独特な趣を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011141"},{"id":"00011139","register_sub_id":"101","register_pk":"205246","name":"東山荘本館","kana":"とうざんそうほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県熱海市春日町1712-5他","lat":35.103884,"lng":139.081793,"geo_status":"db","era":"昭和8／昭和15増築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積240㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"22 - 0224","desc":"相模湾を望む敷地北東寄りに位置する。南北廊下の東側中央を二階建として、上下階とも座敷二室に縁を廻らす。下階は北に玄関棟、南に浴室を配する。全体に木柄が細く、数寄屋を加味した繊細な意匠を基調とし、東面は大きなガラス窓をたて、開放感をもたせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011139"},{"id":"00011144","register_sub_id":"101","register_pk":"205251","name":"東山荘物置","kana":"とうざんそうものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県熱海市春日町1712-6他","lat":35.103811,"lng":139.081668,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造一部鉄筋コンクリート造2階建、瓦葺、建築面積17㎡","structure_material":"木造一部鉄筋コンクリート造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"22 - 0229","desc":"本館南西側に東西棟で建つ、寄棟造桟瓦葺である。一階は敷地の高低差を利用した半地下状で土間一室の物置とし、二階は北側を出桁状に張り出した畳敷の居室で、外壁を簓子下見板張とし、西妻に出入口を設ける。別荘の保守管理の様相を伝える付属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011144"},{"id":"00000731","register_sub_id":"101","register_pk":"101721","name":"常盤家住宅主屋","kana":"ときわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県富士市岩淵455","lat":35.15306562,"lng":138.61874506,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建，瓦葺，建築面積249㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0014","desc":"江戸時代を通し富士川の渡船役を務めた旧家で，主屋は，安政元年の地震後の再建という。間口８間，奥行５間半，切妻造の建屋の四方に庇を付ける。平面は，片側が土間で居室部は整形六間取を基本とする。岩淵宿で「小休本陣」として知られた上質の建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000731"},{"id":"00005464","register_sub_id":"101","register_pk":"106452","name":"中川家住宅（旧高井治兵衛別荘）四阿","kana":"なかがわけじゅうたく（きゅうたかいじへえべっそう）あずまや","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県伊豆の国市奈古谷字神明原708-1","lat":35.07808617,"lng":138.96857746,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造、鉄板葺、面積11㎡","structure_material":"木造","registered":"2006.03.27(平成18.03.27)","register_no":"22 － 0111","desc":"主屋の南から東半に広がる庭の南東隅の一段高い場所に設けられた吹き放ちの四阿。８本の円柱を１．５ｍ間隔に立てた正八角形平面とし，鉄板葺の屋根を架け，軒裏を網代組の化粧とするなど和洋を組み合わせたつくりとする。別荘の庭園景観の構成要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005464"},{"id":"00005461","register_sub_id":"101","register_pk":"106449","name":"中川家住宅（旧高井治兵衛別荘）主屋","kana":"なかがわけじゅうたく（きゅうたかいじへえべっそう）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆の国市奈古谷字神明原708-1","lat":35.07827115,"lng":138.9681105,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積244㎡","structure_material":"木造平屋一部2階建","registered":"2006.03.27(平成18.03.27)","register_no":"22 － 0108","desc":"敷地の北西寄りに北面して建つ。桁行１３．２ｍ，梁間１２．７ｍ，切妻造，フランス瓦葺の木造平屋一部２階建で，南西に平屋の厨房を附属し，庭側に応接室等を設ける。室内意匠も丁寧なつくりで，ハーフティンバーの外観は当時の洋風別荘建築の姿をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005461"},{"id":"00005463","register_sub_id":"101","register_pk":"106451","name":"中川家住宅（旧高井治兵衛別荘）ポンプ室","kana":"なかがわけじゅうたく（きゅうたかいじへえべっそう）ぽんぷしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県伊豆の国市奈古谷字神明原708-1","lat":35.0783503,"lng":138.9679549,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積5.2㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"22 － 0110","desc":"敷地に西辺する道路と主屋北西にある内玄関との間に建つ桁行２．３ｍ，梁間２．２ｍの切妻造，鉄板葺，木造平屋建のポンプ室で，外壁は白塗りの竪板張り，腰をモルタル仕上げとする。南東隅に外部から使う洗い場を設け，両妻側に点検のための開き戸付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005463"},{"id":"00005462","register_sub_id":"101","register_pk":"106450","name":"中川家住宅（旧高井治兵衛別荘）物置","kana":"なかがわけじゅうたく（きゅうたかいじへえべっそう）ものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県伊豆の国市奈古谷字神明原708-1","lat":35.078171,"lng":138.967896,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"22 － 0109","desc":"主屋の南西に建つ。桁行４．４ｍ，梁間４．２ｍ，切妻造，鉄板葺の木造平屋建の物置で，主屋側に小規模な部屋を付属する。東端にコンクリート造隅柱を立て，一部を吹放ちの作業場とする。外壁は下見板張り，腰をモルタル仕上げとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005462"},{"id":"00010456","register_sub_id":"101","register_pk":"199415","name":"沼津倶楽部北棟","kana":"ぬまづくらぶきたとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県沼津市本字千本郷林1907-8","lat":35.087554,"lng":138.852449,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積237㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"22 － 0204","desc":"海浜に臨む勝地に建ち、田字形平面の広間棟と、茶室春日などをもつ座敷棟を雁行配置する。起りを持たせた瓦屋根と丸太垂木で深く差し出す庇が風雅な印象を創る。大小の茶室を巧みに配置し、座敷飾や欄間などに多様な数寄屋技法が駆使され上質で見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010456"},{"id":"00010458","register_sub_id":"101","register_pk":"199417","name":"沼津倶楽部長屋門","kana":"ぬまづくらぶながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県沼津市本字千本郷林1907-8","lat":35.087307,"lng":138.85224,"geo_status":"db","era":"大正2／平成20移築","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、茅葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"22 － 0206","desc":"北棟の西に東西棟で建ち、桁行七メートル規模、寄棟造茅葺である。中央東寄りを門口とし、西室を床板張とする。柱はなぐり仕上げ、壁は中塗仕上げとし、腰に割竹や杉皮、なぐり仕上げの竪板を張るなど、数寄屋意匠を用いた草庵風の佇まいをもつ長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010458"},{"id":"00010457","register_sub_id":"101","register_pk":"199416","name":"沼津倶楽部南棟","kana":"ぬまづくらぶみなみとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県沼津市本字千本郷林1907-8","lat":35.087364,"lng":138.852668,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積206㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"22 － 0205","desc":"十畳主室とサロンを南北軸とし、東西方向に大小の茶室を並べており、外観も複雑で変化に富む。サロンは洋間の空間的雰囲気をもつが丸太柱や網代天井など数寄屋が基調で、他の室も濃厚な数寄屋意匠になり、文人としても著名な施主の好みが具現化されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010457"},{"id":"00012162","register_sub_id":"101","register_pk":"352961","name":"原田家住宅表門","kana":"はらだけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県焼津市浜当目一丁目492","lat":34.880372,"lng":138.330045,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口4.7m","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"22-253","desc":"主屋玄関の南正面に構え、東西両側に棟の高い事務所などが接続する。間口四・七メートル、両下造桟瓦葺。中央間を門口として板扉両開とし東脇間に潜戸を開く。梁を五筋架けて軒桁を受け、壁は漆喰塗で腰を目板付竪板張とする。旧家の表構えに風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012162"},{"id":"00012159","register_sub_id":"101","register_pk":"352958","name":"原田家住宅主屋","kana":"はらだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県焼津市浜当目一丁目492","lat":34.880475,"lng":138.3299,"geo_status":"db","era":"明治8年","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積174㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"22-250","desc":"山裾に所在する敷地中央に南面して建つ。寄棟造桟瓦葺で南・西面に下屋を廻らせる。東端の土間では太い大黒柱を中心に重厚な梁組をみせる。床上部は食違六間取で前列を表向きとし、西端の主室は一〇畳と広めで床を設ける。近世民家形式を継承する上質な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012159"},{"id":"00012161","register_sub_id":"101","register_pk":"352960","name":"原田家住宅文庫蔵","kana":"はらだけじゅうたくぶんこくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県焼津市浜当目一丁目492","lat":34.880636,"lng":138.329811,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"22-252","desc":"主屋背面に東西棟で建ち、桁行七メートル梁間四・六メートル、土蔵造二階建、切妻造桟瓦葺。南面の中央に戸口を開き、桁行全長に持送り付の庇を設ける。外壁漆喰塗で鉢巻を廻らし、南面の腰を海鼠壁とし、両妻面上部に水切を付す。丁寧なつくりの文庫蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012161"},{"id":"00004358","register_sub_id":"101","register_pk":"105348","name":"平井家住宅主屋","kana":"ひらいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県熱海市網代106","lat":35.04680369,"lng":139.09018407,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、瓦葺、建築面積128㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"22 － 0091","desc":"網元として栄えた家の住宅。間口６間半奥行６間，木造２階建，寄棟造，桟瓦葺で，１階の通り側に踏み込み土間を取る以外は良材を用い意匠を凝らした座敷等で構成される。外壁は１階石張，２階大壁漆喰塗とし，開口部に銅板張防火戸を建て重厚な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004358"},{"id":"00004359","register_sub_id":"101","register_pk":"105349","name":"平井家住宅脇門","kana":"ひらいけじゅうたくわきもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県熱海市網代106","lat":35.04670313,"lng":139.09011548,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造、間口1.8m","structure_material":"石造","registered":"2004.11.08(平成16.11.08)","register_no":"22 － 0092","desc":"主屋東妻面の北方に続いて通りと裏庭を仕切る脇門。間口約１間，石造で，門口に方立を立て，成の高いまぐさを架けて両開板戸を吊り込む。まぐさには眉を欠き，石はやや丸みを付けた丁寧な仕上げで，主屋腰部と同じ黒味勝ちの安山岩を用い一体の意匠に整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004359"},{"id":"00014829","register_sub_id":"101","register_pk":"519089","name":"古橋家住宅主屋","kana":"ふるはしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県静岡市葵区平和一丁目173","lat":34.98841944,"lng":138.36785278,"geo_status":"db","era":"昭和3年頃／昭和31年頃改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積231㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"22 - 0324","desc":"静岡浅間神社の北西の市街地に位置する住宅の主屋。二階建桟瓦葺で南西に切妻造玄関ポーチを付す。一階は吹抜の玄関ホールに階段を設け、南庭に面して洋室2室と床構え付き座敷１室を配す。ハーフティンバーの外観が地域の歴史的景観を形成する和洋折衷住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014829"},{"id":"00015020","register_sub_id":"101","register_pk":"529298","name":"古橋家住宅門及び塀","kana":"ふるはしけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県静岡市葵区平和一丁目173","lat":34.98836389,"lng":138.36768056,"geo_status":"db","era":"昭和3年頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"門 鉄筋コンクリート造、間口 3.1m、脇門付 塀 鉄筋コンクリート造、瓦葺、総延長34m","structure_material":"門 鉄筋コンクリート造","registered":"2024.08.15(令和6.08.15)","register_no":"22 - 0330","desc":"静岡浅間神社北西の市街地に位置する和洋折衷住宅の門及び塀。通りに西面する門は柱を石張とし頂部の切妻屋根を釉薬瓦葺とする。両脇に続く塀は、外壁をクリーム色のモルタル塗仕上とし頂部に門と同じ釉薬瓦を葺き、門と一体で地域の歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015020"},{"id":"00002043","register_sub_id":"101","register_pk":"103033","name":"遍界山不去来庵本堂（渡邉家持仏堂）","kana":"へんかいさんふきょらいあんほんどう（わたなべけじぶつどう）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県静岡市葵区両替町1-1","lat":34.97529669,"lng":138.37884572,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積63㎡","structure_material":"土蔵造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"22 － 0072","desc":"駿府城下の両替町の一画に建つ豪商の持仏堂。間口３間半，奥行５間，宝形屋根の土蔵造御堂で，欅材などの良材をふんだんに用い，華麗な天井画のほか，正面扉の金剛力士像など森田鶴堂作の漆喰鏝絵が随所に見られる。棟梁は地元の中村恒吉と小杉清蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002043"},{"id":"00004975","register_sub_id":"101","register_pk":"105965","name":"豊門会館（旧和田豊治家住宅）洋館","kana":"ほうもんかいかん（きゅうわだとよじけじゅうたく）ようかん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県駿東郡小山町藤曲144-8","lat":35.36243018,"lng":138.98673916,"geo_status":"db","era":"明治42／大正14移築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"22 － 0101","desc":"和館南側に位置する。寄棟造で和館との接続部に玄関を設け，南面には出窓を張り出す。外装モルタル塗で，鎧戸付縦長窓を正面に付け，窓上下に木板を帯状に廻し外観を引き締める。大正期以降，都市部で流行した，洋館を和館に付属させる住宅形式の初期の例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004975"},{"id":"00004974","register_sub_id":"101","register_pk":"105964","name":"豊門会館（旧和田豊治家住宅）和館","kana":"ほうもんかいかん（きゅうわだとよじけじゅうたく）わかん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県駿東郡小山町藤曲144-8","lat":35.36257986,"lng":138.98675262,"geo_status":"db","era":"明治42／大正14移築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積344㎡","structure_material":"木造2階一部平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"22 － 0100","desc":"町中心部から北側に位置する豊門公園の東端に建つ。木造２階部分の西側に，平屋を南北に構える大規模住宅。開放的なつくりの庭側は，たちの高い豪壮な構えを見せる。拝に懸魚を付けた入母屋の妻には，半円アーチ形の妻飾を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004974"},{"id":"00010304","register_sub_id":"101","register_pk":"199077","name":"穂積家住宅長屋門","kana":"ほづみけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県磐田市前野字石代2010-1他","lat":34.701422,"lng":137.82141,"geo_status":"db","era":"明治11年／明治30年頃・平成25年移築","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"22-0195","desc":"田園地帯に所在する屋敷地南面に構え、間口一一メートル、寄棟造桟瓦葺である。中央間を門口として扉を吊り、東西を土間の物置とする。外壁は真壁漆喰塗で正背面の腰と両側面を簓子下見板張とし、正面西室に与力窓を設ける。旧家の格式を伝える長屋門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010304"},{"id":"00011136","register_sub_id":"101","register_pk":"205243","name":"前嶋家住宅主屋","kana":"まえじまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県浜松市北区引佐町川名字平505","lat":34.87,"lng":137.703053,"geo_status":"db","era":"江戸後期／江戸末期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積164㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"22 - 0221","desc":"山間の敷地に南面して建つ。東半の土間は屋根を落棟とし、西半は四間取に縁を廻らす。小屋組に土間部が床上部と別棟だった痕跡をもち、ナンド軸部材には蛤刃の加工痕があり古式を示す。当地方に展開した分棟型民家の発展と分布を理解するうえで価値ある住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011136"},{"id":"00007210","register_sub_id":"101","register_pk":"108192","name":"松村家住宅主屋","kana":"まつむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県駿東郡小山町須走字相野尾31-32","lat":35.35936,"lng":138.87783396,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"22 － 0132","desc":"南下り敷地の中央南寄りに南面して建つ、木造平屋建の別荘建築である。屋根は切妻造で、土間と食堂の東西棟の西端に、南北棟の和室が接続する。外壁はモルタル塗で、基礎などをスクラッチタイル貼とする。土間と食堂に設けた上げ下げ窓が印象的な外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007210"},{"id":"00005883","register_sub_id":"101","register_pk":"106868","name":"三嶋暦師の館（旧河合家住宅主屋）","kana":"みしまごよみしのやかた（きゅうかわいけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県三島市大宮町2-5-16","lat":35.122875,"lng":138.92157,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積218㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"22 － 0113","desc":"三嶋大社東方の屋敷地に北面して建つ。桁行９間半，梁間４間半，切妻造，桟瓦葺で，北面中央に起り破風の式台玄関を構える。東方を土間，西方を２列６室とし，北西隅に８畳座敷を配する。関所建物の移築と伝えるが，江戸末期有力社家の住宅遺構としても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005883"},{"id":"00004551","register_sub_id":"101","register_pk":"105541","name":"眠雲閣落合樓住居棟及び廊下","kana":"みんうんかくおちあいろうじゅうきょとうおよびろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市湯ヶ島1887-1","lat":34.88980096,"lng":138.927719,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造地上2階地下1階建、瓦葺、建築面積128㎡、廊下 木造平屋建、鉄板葺、建築面積20㎡","structure_material":"木造地上2階地下1階建","registered":"2005.02.09(平成17.02.09)","register_no":"22 － 0097","desc":"玄関棟から東に向かう廊下と連絡する旅館主の居宅。地階に浴室を置く３層構成で，１階は玄関，洋室，８畳と１０畳の和室，２階は８畳和室と洋室２室から成る。凝った意匠の建具組子や吟味された材料など，随所に昭和初期の建築技術と施主の好みが表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004551"},{"id":"00010603","register_sub_id":"101","register_pk":"201177","name":"ヤマタケの蔵北の蔵","kana":"やまたけのくらきたのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県浜松市天竜区二俣町二俣字中町1162-4","lat":34.866837,"lng":137.815202,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階一部平屋建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階一部平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"22－0212","desc":"新蔵の北側に東西棟で建つ土蔵造二階建で、東端を落棟の平屋建とし、切妻造桟瓦葺である。主体部と平屋部の南面に戸口を開き、南西面に窓を穿つ。外壁は漆喰塗で鉢巻を廻らし、西妻面はモルタル塗の下屋を張出し、新蔵同様の外観として街路景観の調和を図る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010603"},{"id":"00010601","register_sub_id":"101","register_pk":"201175","name":"ヤマタケの蔵新蔵","kana":"やまたけのくらしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市天竜区二俣町二俣字中町1162-4","lat":34.866776,"lng":137.815163,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積39㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"22－0210","desc":"敷地西奥に東面し、木造二階建、切妻造桟瓦葺である。外壁はモルタル塗で、腰を洗出し仕上げ、上部は石造風に目地を切る。衣裳部屋として建てられ、上下階とも座敷二室を配して地袋を造作し、下階に電話室を設ける。ケヤキやスギの良材を用いた良質な座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010601"},{"id":"00010602","register_sub_id":"101","register_pk":"201176","name":"ヤマタケの蔵南の蔵","kana":"やまたけのくらみなみのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市天竜区二俣町二俣字中町1162-4","lat":34.866706,"lng":137.815211,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造平屋建、瓦葺、建築面積40㎡、門付","structure_material":"煉瓦造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"22－0211","desc":"新蔵の南側に東西棟で建ち、新蔵との間に欠円アーチの門を開く。細長い平面の煉瓦造平屋建で、外壁南面はイギリス積煉瓦壁を現し、他はモルタル塗で石造風に目地を切る。内部は東から使用人部屋、便所、倉庫に間仕切る。実業家の屋敷構えの様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010602"},{"id":"00012746","register_sub_id":"101","register_pk":"367649","name":"陽明館","kana":"ようめいかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県熱海市桃山町7-3他","lat":35.1064,"lng":139.075115,"geo_status":"db","era":"昭和14年／昭和33年改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積157㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"22 － 255","desc":"山麓の敷地に南面して建つ木造二階建の別荘。上下階とも相模湾を望む東半南側に和室二室を並べ、広縁を通した開放的なつくりで、西面中央の玄関南脇に畳敷の小上がり付の洋室を設ける。木割が細く、面皮材や丸太を多用し、細部を瀟洒な数寄屋意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012746"},{"id":"00010459","register_sub_id":"101","register_pk":"199418","name":"吉澤家住宅煉瓦蔵","kana":"よしざわけじゅうたくれんがぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県富士宮市宮町947-1","lat":35.224805,"lng":138.608187,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"22 － 0207","desc":"浅間大社の門前に位置する文具店後方に北面し、土蔵造二階建で北に下屋を設ける。下屋は軸組の外側に長手に積んだ煉瓦壁を内面に現し、主体部も同様に煉瓦積を内包する木骨煉瓦工法とみられる。明治期に市内で盛んに建てられた煉瓦蔵の希少な遺例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010459"},{"id":"00006023","register_sub_id":"101","register_pk":"107008","name":"吉田家住宅主屋","kana":"よしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県静岡市清水区蒲原2-6-21","lat":35.120014,"lng":138.6064,"geo_status":"db","era":"明治20頃／明治42頃・大正期増築","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積200㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"22 － 0119","desc":"旧東海道に面して建つ。間口３間，奥行７間半，塗屋造つし２階建，切妻造とし，東側に通り土間を設け，西側に３室を並べた町家の形態とする。正面に奥行１間の下屋を設け，腰壁を海鼠壁で飾る。主屋西側に増築した座敷部分も塗屋造とし，特徴のある外観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006023"},{"id":"00001356","register_sub_id":"101","register_pk":"102346","name":"依田家住宅表門","kana":"よだけじゅうたくおもてもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県賀茂郡松崎町大沢153","lat":34.75795949,"lng":138.82989738,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"22 － 0050","desc":"賀茂川右岸の旧街道に面して建つ切妻造，瓦葺の長屋門。間口が切り縮められているが，両開きの板戸と片開きの潜り戸を設けた通り口と，その東側半間分の１室が残る。名主を務めるとともに回船業を営んでいた旧家の表構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001356"},{"id":"00001359","register_sub_id":"101","register_pk":"102349","name":"依田家住宅カマヤ","kana":"よだけじゅうたくかまや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"静岡県","address":"静岡県賀茂郡松崎町大沢153","lat":34.75821617,"lng":138.83001599,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積33㎡","structure_material":"土蔵造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"22 － 0053","desc":"主屋の東方に位置する平屋建て，土蔵造の建築。屋根は，切妻造，桟瓦葺で，南妻を正面とする。腰壁の一部を下見板張とし，妻壁はなまこ壁で，煙出窓を設ける。主屋と別棟の釜屋を構えた古い時期の屋敷構えを伝えるものとして数少ない例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001359"},{"id":"00001357","register_sub_id":"101","register_pk":"102347","name":"依田家住宅中門","kana":"よだけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県賀茂郡松崎町大沢153","lat":34.75803397,"lng":138.82986651,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、長さ2.5m、板塀14.5m附属","structure_material":"木造","registered":"1999.10.14(平成11.10.14)","register_no":"22 － 0051","desc":"表門の北方約６メートルに位置して建つ瓦葺，切妻屋根の棟門。親柱間に両開きの板扉を構え，親柱の斜め後方に控柱を備える。左右に竪板張りの板塀が接続して主屋の前面を画しており，屋敷構えを構成する主要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001357"},{"id":"00001358","register_sub_id":"101","register_pk":"102348","name":"依田家住宅塀","kana":"よだけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県賀茂郡松崎町大沢153","lat":34.75807358,"lng":138.82965312,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、延長22.5m","structure_material":"木造","registered":"1999.10.14(平成11.10.14)","register_no":"22 － 0052","desc":"主屋の南面から西面にかけて矩折りに曲がる真壁造の土塀。総延長１８間で，内側には２間毎に控え柱を立て，屋根は桟瓦葺とする。白漆喰塗りで，外側は腰下見板張とする。東南方に接続する板塀とともに棟の高さを変えながら塀が雁行型に連なる姿に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001358"},{"id":"00000347","register_sub_id":"101","register_pk":"101337","name":"隆泉苑","kana":"りゅうせんえん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県三島市中田町1-43","lat":35.11588488,"lng":138.9158353,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積324㎡","structure_material":"木造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"22 － 0006","desc":"佐野美術館の創始者佐野隆一が両親に贈った旧邸宅を，昭和５２年に美術館に寄贈したもの。総平屋建で，書院の間，数寄屋の間，応接の間等複数の棟から構成される。いずれも吟味された材料を用いて上質かつ繊細に仕上げた作品で，近代和風住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000347"},{"id":"00000411","register_sub_id":"101","register_pk":"101401","name":"隆泉苑表門","kana":"りゅうせんえんおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県三島市中田町1-43","lat":35.11570909,"lng":138.91624584,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造四脚門袖塀付，瓦葺","structure_material":"木造四脚門袖塀付","registered":"1997.12.12(平成9.12.12)","register_no":"22 － 0008","desc":"間口の広い両袖塀付の四脚門で，切妻造，桟瓦葺になる。表門の意匠は，左右の袖壁と一体的で，上端を開放的に仕上げ土壁の腰下を縦板貼とする。全体に簡潔な造作としながら，ケヤキの一枚板を用いた門扉は見応えがあり，訪れる人々を魅了している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000411"},{"id":"00004578","register_sub_id":"101","register_pk":"105568","name":"伊藤家住宅蔵","kana":"いとうけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券677","lat":35.38330742,"lng":136.9398526,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0182","desc":"主屋東裏，敷地の最奥に建つ。桁行４間半，梁間２間半，土蔵造２階建，切妻造，桟瓦葺，平入で，西面の戸前全面に出が１間半の深い庇を付す。柱は丸太で，軒裏や妻面の破風，桁端を塗り込めただけの簡素な造りだが，比較的大型でたちの低い重厚な構えをもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004578"},{"id":"00007640","register_sub_id":"101","register_pk":"108622","name":"伊藤家住宅腰掛待合","kana":"いとうけじゅうたくこしかけまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県津島市橘町4-84","lat":35.17262226,"lng":136.73241713,"geo_status":"db","era":"昭和23","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.2㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"23 － 0318","desc":"水鶏庵に伴う待合で庭園西側の中ほどに建つ。桁行２．７ｍ梁間１．２ｍ、木造平屋建、招造屋根の銅板葺で、三方の壁を土壁とし、右手の壁には下地窓を穿つ。軸部材は主として丸太を用い、軒は竹垂木とする。水鶏庵とともに落ち着いた露地空間を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007640"},{"id":"00007637","register_sub_id":"101","register_pk":"108619","name":"伊藤家住宅茶席水鶏庵","kana":"いとうけじゅうたくちゃせきくいなあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県津島市橘町4-85","lat":35.17250373,"lng":136.73242934,"geo_status":"db","era":"明治元／昭和23移築","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"23 － 0315","desc":"庭園南西隅の木立に建つ。桁行５．９ｍ梁間５．０ｍ規模、木造平屋建、寄棟造銅板葺である。トコを備えた四畳半規模の茶室に次の間を付け、茶室の北東面に幅広の榑縁と高欄付切目縁をめぐらし、庇をかける。庭の眺望を意識した、開放的なつくりの近代茶席。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007637"},{"id":"00004255","register_sub_id":"101","register_pk":"105245","name":"井上家住宅蔵","kana":"いのうえけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字西古券6","lat":35.38367494,"lng":136.939055,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0149","desc":"主屋から裏庭を挟んで奥行の長い敷地の西端に建つ。桁行３間梁間２間の土蔵造２階建の南北棟で，屋根は切妻造，桟瓦葺とする。東面に庇をつける。外壁は全体を押縁下見板張とする。２階の妻側と平側に窓を開き，妻側窓には庇をつける。敷地の構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004255"},{"id":"00004249","register_sub_id":"101","register_pk":"105239","name":"梅田家住宅高塀","kana":"うめだけじゅうたくたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券506","lat":35.38316798,"lng":136.94269926,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、延長9.1m","structure_material":"木造","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0143","desc":"敷地の西側道路に面する塀で，主屋の南西角と倉庫の北西角との間をつなぐ。長さ５間を７分割して柱を立てる。腰は墨塗の南京下見板張，上部は真壁造で白漆喰仕上とする。柱から腕木を出して桁を受け，片流れ２枚の桟瓦葺の屋根をかける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004249"},{"id":"00010610","register_sub_id":"101","register_pk":"201184","name":"大倉公園茅葺門（旧大倉和親別荘表門）","kana":"おおくらこうえんかやぶきもん（きゅうおおくらかずちかべっそうおもてもん）","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県大府市桃山町5-74他","lat":35.012593,"lng":136.965883,"geo_status":"db","era":"大正11年頃／昭和54年移築","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、茅葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"23－0427","desc":"切妻造茅葺の長屋門で、中央の門口部の屋根を一段切上げる。門扉は両開きの板戸で、東脇に潜を設ける。もとは前面道路に接して左右に長屋を従え、雄大な屋敷の正面構えを構成していた。実業家の別荘の表構えをつくる独特な形式の門で、素朴と風格を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010610"},{"id":"00010609","register_sub_id":"101","register_pk":"201183","name":"大倉公園休憩棟（旧大倉和親別荘離れ）","kana":"おおくらこうえんきゅうけいとう（きゅうおおくらかずちかべっそうはなれ）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県大府市桃山町5-77他","lat":35.01302,"lng":136.965164,"geo_status":"db","era":"大正11年頃／平成20年改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積209㎡、地下室付","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"23－0426","desc":"もと別荘の離れで、接客用の座敷などを矩折れに配して庭側に縁を廻らす。中央に配膳室を置いて、各座敷への給仕動線が短くなるよう考慮されている。長押に磨き丸太を用いたり、蟻壁の開口部に割竹を用いるなど、数寄屋風の意匠になる瀟洒な別荘建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010609"},{"id":"00009467","register_sub_id":"101","register_pk":"194260","name":"大島家住宅茶室","kana":"おおしまけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字西古券21-1他","lat":35.38295307,"lng":136.93869948,"geo_status":"db","era":"文政9年／明治期移築・昭和61年曳家","year":1826,"year_source":"db","year_min":1826,"year_max":1826,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"23 － 0365","desc":"主屋南側の西奥に東面して建つ。切妻造桟瓦葺、木造平屋建、四畳半茶室の南に水屋と鞘の間を配す。手前座天井を一段低く網代天井とし、客座天井は一段高く竹棹縁のね板張りとする利休好みの四畳半茶室の構成とする。瀟洒なつくりの数寄屋建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009467"},{"id":"00011964","register_sub_id":"101","register_pk":"211155","name":"大谷家住宅米蔵","kana":"おおたにけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊川市足山田町下平100・101合併地他","lat":34.86548,"lng":137.406436,"geo_status":"db","era":"昭和3年頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積23㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"23-503","desc":"敷地の南面に位置する。鉄筋コンクリート造二階建で、陸屋根とし、外壁はモルタル仕上げ。内部は、前室と後室に区分し、前室は階段室で上部にヴォールト天井をあしらう。正面は片引戸で西側面及び背面に一所ずつ片開き窓を穿つ他は閉鎖的で防火に優れた米蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011964"},{"id":"00011962","register_sub_id":"101","register_pk":"211153","name":"大谷家住宅主屋","kana":"おおたにけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県豊川市足山田町下平100・101合併地","lat":34.865717,"lng":137.406346,"geo_status":"db","era":"大正5年／平成6年・同18年増築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建一部地下1階、瓦葺、建築面積249㎡","structure_material":"木造2階建一部地下1階","registered":"2017.10.27(平成29.10.27)","register_no":"23-501","desc":"豊川市北部の本宮山麓の敷地に西面する。中央の式台玄関から北に座敷や仏間など二列各二室、南に居室、台所などを配し、各室へは中廊下で通ずる。居室部からコンクリート造の地下室や二階へ続く。軸部は太く、領有する山から切り出したとされる材は良質である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011962"},{"id":"00011963","register_sub_id":"101","register_pk":"211154","name":"大谷家住宅土蔵","kana":"おおたにけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県豊川市足山田町下平100・101合併地他","lat":34.865863,"lng":137.406262,"geo_status":"db","era":"大正5年頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"23-502","desc":"敷地の北東隅に西面する。桁行二間半、梁間二間、土蔵造、平入で、正面に下屋を付ける。外壁は、腰壁を下見板張とし、正面のみ海鼠壁とする。背面及び側面の窓は、繰型のある持送りを付け、窓枠を黒漆喰仕上げとするなど、敷地後方の景観を良好に形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011963"},{"id":"00011965","register_sub_id":"101","register_pk":"211156","name":"大谷家住宅渡廊下","kana":"おおたにけじゅうたくわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県豊川市足山田町下平100・101合併地","lat":34.865817,"lng":137.406274,"geo_status":"db","era":"大正5年頃／平成6年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積2.5㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"23-504","desc":"主屋と土蔵を結ぶ木造、切妻造の渡廊下。桁行二間、梁間半間で、腰壁を下見板張とし、庭園に面する西側は上部を鼠漆喰仕上げとする。内部は、桁上に丸太状の梁を架け、化粧屋根裏とし、数寄屋風の意匠を見せる。敷地景観を構成する付属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011965"},{"id":"00001269","register_sub_id":"101","register_pk":"102259","name":"奥村家住宅米蔵","kana":"おくむらけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券395","lat":35.38290407,"lng":136.94457121,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造２階建，瓦葺，建築面積51㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"23 － 0027","desc":"南北に長い敷地の南寄り、棟門に向き合う位置に建つ南北棟、瓦葺切妻屋根の２階建土蔵。桁行５間半、梁間３間半の比較的規模の大きな蔵で、西面の北寄りに扉を開く。並んで建つ道具蔵、離れとともに敷地中央部の奥向空間の主要構成要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001269"},{"id":"00001270","register_sub_id":"101","register_pk":"102260","name":"奥村家住宅道具蔵","kana":"おくむらけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券395","lat":35.38289217,"lng":136.94451259,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造２階建，瓦葺，建築面積31㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"23 － 0028","desc":"敷地中央部の奥向空間の構成要素のひとつで、米蔵の西側に建つ。南北棟、瓦葺切妻屋根、妻入の２階建土蔵で、３間四方の規模を有し、北面のやや西寄りに扉を開く。米蔵よりもたちが高く、鳥衾付きの鬼瓦を挙げるなど上質なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001270"},{"id":"00001272","register_sub_id":"101","register_pk":"102262","name":"奥村家住宅納屋","kana":"おくむらけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券395","lat":35.38299034,"lng":136.94461166,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建，瓦葺，建築面積16㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"23 － 0030","desc":"棟門から米蔵へ向かう小路的通り筋の奥に東高塀に沿って建つ。米蔵の北面と東高塀と壁を共有する細長い平面の瓦葺片流れ屋根、真壁造りの建屋で、内部を３室に分ける。西面に３つの出入口を開き渡り廊との間に特徴的な路地的空間をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001272"},{"id":"00001271","register_sub_id":"101","register_pk":"102261","name":"奥村家住宅離れ","kana":"おくむらけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券395","lat":35.3829,"lng":136.944458,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造２階建，瓦葺，建築面積37㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"23 － 0029","desc":"道具蔵の西側に接して建つ木造２階建の数寄屋風の離れ。道具蔵と接する東側は土間とし、道具蔵の蔵前右手に入口を設ける。西側には８畳間を配して南と北に縁側を設け、北縁には月見台風の簀子縁を張出す。屋敷構えの発展過程を物語る遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001271"},{"id":"00001274","register_sub_id":"101","register_pk":"102264","name":"奥村家住宅東高塀","kana":"おくむらけじゅうたくひがしたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券395","lat":35.3831157,"lng":136.94461234,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造，瓦葺，延長17.4m","structure_material":"木造","registered":"1999.08.23(平成11.08.23)","register_no":"23 － 0032","desc":"敷地の東境に沿って、棟門から納屋北面までの間に建てられた木造瓦葺、漆喰塗仕上げの塀で、棟門の南面庇ほどの高さがあることから高塀と呼ばれる。補強のためのバットレス状の控柱型をつけていることも特徴のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001274"},{"id":"00001273","register_sub_id":"101","register_pk":"102263","name":"奥村家住宅渡り廊","kana":"おくむらけじゅうたくわたりろう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券395","lat":35.382996,"lng":136.94453876,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建，瓦葺，建築面積66㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"23 － 0031","desc":"主屋の南東端と米蔵とをつなぐ南北棟、瓦葺切妻屋根の渡り廊で、米蔵の蔵前部で道具蔵の北面庇と一体になる。井戸屋形を兼ねた造りで、西面を吹放ちとし、東側南半に使用人部屋と便所を配し、東面の腰に煉瓦を貼る。屋敷構えの主要な構成要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001273"},{"id":"00001276","register_sub_id":"101","register_pk":"102266","name":"尾関家住宅主屋","kana":"おぜきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字白山平２ 他","lat":35.38689497,"lng":136.95097545,"geo_status":"db","era":"天保13","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"木造２階建，瓦葺，建築面積171㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"23 － 0034","desc":"犬山焼を復興した窯元の屋敷。犬山藩の御用瓦師時代に大火の出火元となったために現在地に移転した時のもの。東西棟、瓦葺切妻屋根、平入の２階建で、東側に土間をとり、西側南に床棚付き８畳ほか３室を並べ、北に仏間、納戸などを配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001276"},{"id":"00001277","register_sub_id":"101","register_pk":"102267","name":"尾関家住宅土蔵","kana":"おぜきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字白山平２ 他","lat":35.38697004,"lng":136.95082886,"geo_status":"db","era":"天保13","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積28㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"23 － 0035","desc":"主屋の北西方に建つ南北棟、瓦葺切妻屋根、平入の２階建土蔵。桁行４間、梁間２間の規模で、東面に１間分の庇を差掛けて蔵前をとり、南端で主屋仏間北側の縁側につなげる。南面は下見板貼りに改装されているが、開口の少ない閉鎖的な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001277"},{"id":"00009612","register_sub_id":"101","register_pk":"194608","name":"小野田家住宅主屋","kana":"おのだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県豊橋市高塚町字郷中65","lat":34.66302303,"lng":137.40006314,"geo_status":"db","era":"明治19／大正9増築","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造2階建、瓦葺、建築面積292㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"23 － 0376","desc":"屋敷地中央に南面して建つ。主体部は寄棟造桟瓦葺の二階建で、西に増築部の座敷棟を接続する。一階は東に土間、西に二列六室の居室を設け、二階には納戸と中廊下型の四室を設ける。座敷はトコや建具に意匠を凝らし、手の込んだ上質で丁寧なつくりとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009612"},{"id":"00009613","register_sub_id":"101","register_pk":"194609","name":"小野田家住宅長屋門","kana":"おのだけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊橋市高塚町字郷中65","lat":34.66291595,"lng":137.40044385,"geo_status":"db","era":"嘉永2頃","year":1849,"year_source":"db","year_min":1849,"year_max":1849,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"23 － 0377","desc":"主屋の南方に南面して建つ。桁行一七メートル、梁間四・六メートルの大規模な長屋門で、入母屋造桟瓦葺。門口に両開き板戸と潜り戸を開き、東方に一室、西方に二室の納屋を持つ。外壁は漆喰仕上げで、下部に簓子下見を張る。風格ある屋敷構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009613"},{"id":"00009760","register_sub_id":"101","register_pk":"195589","name":"筧家住宅主屋","kana":"かけひけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中村区下米野町3-29","lat":35.16067278,"lng":136.87680083,"geo_status":"db","era":"江戸末期／明治初期移築・明治24増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（銅板仮葺）、建築面積129㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0381","desc":"名古屋駅の約一キロメートル南方に所在する。江戸末期の建築を明治初期に移築した主体部と、同二四年に増築した小屋部からなる。整型四間取の主体部は、はじめに四本の上屋柱を立てて梁と差物で繋ぐ「四つ建て」工法を採用し、当地域の民家の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009760"},{"id":"00007047","register_sub_id":"101","register_pk":"108029","name":"神谷家住宅井戸屋形","kana":"かみやけじゅうたくいどやかた","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県安城市和泉町上之切13","lat":34.92470877,"lng":137.04607139,"geo_status":"db","era":"明治後期／昭和前期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、面積18㎡","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0298","desc":"横屋の北に隣接して建つ。桁行３．７ｍ梁間２．８ｍ、切妻造桟瓦葺の主体部に、庇を東・北面に付けて拡張。主体部は内転びのある柱を４本建て、中央に切石組の井戸枠を組み、周囲を洗い場とする。主体部は吹放ち、庇部には下見板を張る。中央に釣瓶の滑車も残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007047"},{"id":"00007039","register_sub_id":"101","register_pk":"108021","name":"神谷家住宅奥座敷","kana":"かみやけじゅうたくおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県安城市和泉町上之切13","lat":34.92483704,"lng":137.0460315,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0290","desc":"敷地の北寄りに建つ。 建築面積１４７㎡、木造平屋建、寄棟造及び切妻造、桟瓦葺。１０畳２室とトコ付９畳、８畳を田の字型に配し、その周囲に縁をまわし、北面に茶室を設ける。天井の棹縁に丸竹を使うなど全体に数寄屋意匠を採用する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007039"},{"id":"00007044","register_sub_id":"101","register_pk":"108026","name":"神谷家住宅奥の蔵","kana":"かみやけじゅうたくおくのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県安城市和泉町上之切13","lat":34.924843,"lng":137.04580219,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0295","desc":"敷地のほぼ中央、奥座敷の西方に建つ。桁行８．２ｍ梁間４．８ｍ、土蔵造２階建、切妻造桟瓦葺で、南妻を正面入口とし、蔵前を付ける。外壁は、南妻面と窓まわりなどを漆喰塗籠とし、その他は簓子下見板張とする。主屋に近接し、日常の用途に供する道具蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007044"},{"id":"00007048","register_sub_id":"101","register_pk":"108030","name":"神谷家住宅釜屋及び物置","kana":"かみやけじゅうたくかまやおよびものおき","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県安城市和泉町上之切13","lat":34.92474407,"lng":137.04615319,"geo_status":"db","era":"明治前期／昭和前期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積13㎡、塀付","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0299","desc":"敷地の東辺、横屋の北側に建つ。桁行１４ｍ梁間１．８ｍの細長い木造平屋建で、桟瓦葺の招屋根。通り側を黒塗の簓子下見板張として高塀のように見せる。南・北両端桁行３．５ｍを物置とし、その間の桁行７ｍを、西面吹放ちの釜屋とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007048"},{"id":"00009288","register_sub_id":"101","register_pk":"194081","name":"神谷家住宅孤葊","kana":"かみやけじゅうたくこあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中区新栄2-1004","lat":35.16852411,"lng":136.9217253,"geo_status":"db","era":"江戸末期／明治44年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0342","desc":"柏露軒南面西寄りに、庭に面して建つ。木造平屋建、建築面積一〇平方メートル、切妻造銅板葺で、内部は台目畳三畳敷の茶室と水屋からなる。床柱の太い丸太や、七宝繋彩色の残るトコの落掛けは名古屋城普請の古材と伝える。独特の由緒と創意のみられる茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009288"},{"id":"00009289","register_sub_id":"101","register_pk":"194082","name":"神谷家住宅腰掛待合","kana":"かみやけじゅうたくこしかけまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県名古屋市中区新栄2-1004","lat":35.16854315,"lng":136.92166106,"geo_status":"db","era":"大正12年／平成7年曳家","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.3㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0343","desc":"孤葊と庭を挟んで向き合う。木造平屋建、桁行二・四メートル梁間一・四メートル、切妻造銅板葺である。壁は土壁で腰に杉皮を張り、南の正客席側は、壁を半月形の窓を開ける。軸部はナグリ仕上げやツラ付の丸太などを用いて、風情ある趣を醸している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009289"},{"id":"00007042","register_sub_id":"101","register_pk":"108024","name":"神谷家住宅米蔵","kana":"かみやけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県安城市和泉町上之切13","lat":34.924641,"lng":137.045532,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積80㎡","structure_material":"土蔵造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0293","desc":"敷地南辺の西端に建つ。桁行１１ｍ梁間７．３ｍ、土蔵造平屋建、切妻造桟瓦葺で、東面に庇を付ける。外壁は、水切り下を黒塗の簓子下見板張とし、東面は腰を海鼠壁とする。内部は広く、小屋は三重に梁を重ねる。屋敷の前庭空間に重厚感を与える大型土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007042"},{"id":"00007040","register_sub_id":"101","register_pk":"108022","name":"神谷家住宅左官部屋及び炭部屋","kana":"かみやけじゅうたくさかんべやおよびすみべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県安城市和泉町上之切13","lat":34.92449623,"lng":137.04572112,"geo_status":"db","era":"明治38頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0291","desc":"正門と一連の建物で、敷地南辺に建つ。建築面積３２㎡、木造平屋建、切妻造桟瓦葺。正門より棟を一段高め、敷地内側の庇は正門の庇と軒を揃える。外壁は黒塗の簓子下見板張で、小壁は真壁造で漆喰仕上げとしており、屋敷構えに重厚感を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007040"},{"id":"00007038","register_sub_id":"101","register_pk":"108020","name":"神谷家住宅座敷","kana":"かみやけじゅうたくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県安城市和泉町上之切13","lat":34.924637,"lng":137.0457,"geo_status":"db","era":"明治前期／大正期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0289","desc":"南面する敷地の南寄り、前庭に面して建つ。 建築面積８５㎡、木造平屋建、寄棟造妻入桟瓦葺で、周囲に庇をまわす。接客用の座敷で、８畳２室の座敷に茶室を付設する。座敷は円形下地窓や座敷飾りを備え、茶室は良材を用いた上質なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007038"},{"id":"00007043","register_sub_id":"101","register_pk":"108025","name":"神谷家住宅雑穀蔵","kana":"かみやけじゅうたくざっこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県安城市和泉町上之切13","lat":34.92448669,"lng":137.04594327,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0294","desc":"敷地東辺の南寄り、正門と横屋の間に建ち、屋敷地東面の重要な景観要素となっている。桁行９．１ｍ梁間４．６ｍ、土蔵造２階建、切妻造桟瓦葺。外壁は、鉢巻の下部までを黒塗の簓子下見板張とし、窓庇の持送りには漆喰で渦紋を象り、意匠を凝らせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007043"},{"id":"00007051","register_sub_id":"101","register_pk":"108033","name":"神谷家住宅正門","kana":"かみやけじゅうたくせいもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県安城市和泉町上之切13","lat":34.92443123,"lng":137.04586319,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0302","desc":"敷地正面に建つ長屋門。桁行１４ｍ梁間３．６ｍの平屋建、東入母屋造及び西切妻造の桟瓦葺。外壁を簓子下見板張とし、正面の小壁は大壁塗で隅柱のみ現す。東に物置、西に道具部屋を設け、間に潜り付の門口を開く。屋敷の正面入口として重厚な外観をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007051"},{"id":"00007050","register_sub_id":"101","register_pk":"108032","name":"神谷家住宅大工部屋及び奥和室","kana":"かみやけじゅうたくだいくべやおよびおくわしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県安城市和泉町上之切13","lat":34.92514058,"lng":137.04579027,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0301","desc":"味噌蔵及び書庫と一連の建物で、敷地北辺に建つ。桁行１１ｍ梁間５．６ｍの平屋建、切妻造桟瓦葺で、南面に１．８ｍ幅の庇を付設。北面外壁は味噌蔵及び書庫と同意匠とする。南面の庇と一体的な大工部屋は高い内部空間をもち、独特な梁組の小屋組を採用する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007050"},{"id":"00009290","register_sub_id":"101","register_pk":"194083","name":"神谷家住宅中潜門","kana":"かみやけじゅうたくなかくぐりもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市中区新栄2-1004","lat":35.16853363,"lng":136.92168961,"geo_status":"db","era":"昭和前期／平成7年曳家","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、間口1.7m","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0344","desc":"敷地の南寄り、孤葊の南西側に建つ。間口一・七メートルの一間腕木門、切妻造銅板葺で、潜戸片引きとする。ナグリ仕上げの柱に腕木をつけて丸太の桁を受ける。北側の腕木は他建物の柄振り板を転用したとみられ、上面に絵様を彫る。良質な露地空間を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009290"},{"id":"00009287","register_sub_id":"101","register_pk":"194080","name":"神谷家住宅柏露軒","kana":"かみやけじゅうたくはくろけん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中区新栄2-1004","lat":35.16857408,"lng":136.92172768,"geo_status":"db","era":"江戸末期／明治44年移築・昭和4年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0341","desc":"敷地中央に北面して建つ。木造平屋建、建築面積七八平方メートル、切妻造桟瓦葺及び銅板葺。広間茶室の柏蔭斎、容膝、大炉の間からなる主棟に、相伴席付一畳台目茶室磑亭を附属する。柏蔭斎の欄間を玄々斎好みの扇面散しとするなど瀟洒なつくりの数寄屋建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009287"},{"id":"00007045","register_sub_id":"101","register_pk":"108027","name":"神谷家住宅宝蔵","kana":"かみやけじゅうたくほうぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県安城市和泉町上之切13","lat":34.92501539,"lng":137.04572447,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0296","desc":"敷地の北西方、３段の御影石積上に建つ。桁行９．１ｍ梁間５．５ｍ、土蔵造２階建、切妻造桟瓦葺で、南面に庇を付ける。外壁は、水切りを３段付けて腰を海鼠壁とする。庇の軒を塗り込め、開口部の造作も丁寧に造るなど、重厚かつ華やかな外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007045"},{"id":"00007049","register_sub_id":"101","register_pk":"108031","name":"神谷家住宅味噌蔵及び書庫","kana":"かみやけじゅうたくみそぐらおよびしょこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県安城市和泉町上之切13","lat":34.92507688,"lng":137.0459047,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積40㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0300","desc":"大工部屋及び奥和室と一連の建物で、敷地北辺に建つ。桁行１１ｍ梁間３．６ｍの木造２階建、切妻造桟瓦葺。南面に庇を設け、東妻面は漆喰で塗り込め、北面外壁は腰高の簓子下見板張とする。１階は３室に間仕切り、西から味噌蔵、物置、書庫とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007049"},{"id":"00007046","register_sub_id":"101","register_pk":"108028","name":"神谷家住宅横屋","kana":"かみやけじゅうたくよこや","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県安城市和泉町上之切13","lat":34.92459238,"lng":137.04601081,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積41㎡、塀付","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0297","desc":"敷地東辺の中ほどに建つ。桁行１１ｍ梁間３．７ｍ、木造平屋建、切妻造桟瓦葺。通り側は簓子下見板張とするのに対し、敷地内側は真壁造で、濡縁を設ける。雑穀蔵などの隣接する建物と統一感のある外観とし、屋敷地東面の景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007046"},{"id":"00007041","register_sub_id":"101","register_pk":"108023","name":"神谷家住宅渡り","kana":"かみやけじゅうたくわたり","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県安城市和泉町上之切13","lat":34.924545,"lng":137.04561339,"geo_status":"db","era":"明治38頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"23 － 0292","desc":"左官部屋及び炭部屋の西側に連続して建ち、西端は米蔵に接続する。桁行１３ｍ梁間１．８ｍ、木造平屋建、切妻造桟瓦葺。通り側は左官部屋及び炭部屋と意匠を揃えるが、軒をやや低める。敷地内側は吹放ちの土間とし、荷物置場などとして使用した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007041"},{"id":"00012559","register_sub_id":"101","register_pk":"367854","name":"川田家住宅主屋","kana":"かわたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県丹羽郡扶桑町大字南山名字前ノ前49","lat":35.363495,"lng":136.905731,"geo_status":"geocoded","era":"明治24年頃／大正6年移築","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積196㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0530","desc":"木曽川南岸の集落の農家主屋で、敷地北寄りに南面して建つ。町家の移築で入母屋造桟瓦葺二階建の外観や二列三室の平面に特徴を残すが、表裏を逆転して座敷を正面に向け、二階を蚕室にするなど農家の特徴を併せもつ。伝統的な農村景観に変化をつける大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012559"},{"id":"00013256","register_sub_id":"101","register_pk":"366245","name":"川原田家住宅石垣","kana":"かわらだけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市昭和区南山町25-4他","lat":35.14204722,"lng":136.95053889,"geo_status":"db","era":"昭和13年頃","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造、総延長33m","structure_material":"鉄筋コンクリート造","registered":"2020.04.03(令和2.04.03)","register_no":"23 － 0545","desc":"敷地の西面及び南面の一部の敷地境界に廻り、鉄筋コンクリート造のＬ型擁壁に大谷石を切石布積風に貼る。上端に笠石を載せ、様々な種類の樹木を植えた生垣とする。敷地周縁部を構成すると共に、住宅地の良好な景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013256"},{"id":"00013255","register_sub_id":"101","register_pk":"366244","name":"川原田家住宅裏門及び塀","kana":"かわらだけじゅうたくうらもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市昭和区南山町25-5","lat":35.14195,"lng":136.95075278,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"門 木造、瓦葺、間口1.7m 塀 木造、瓦葺、総延長15m","structure_material":"門 木造","registered":"2020.04.03(令和2.04.03)","register_no":"23 － 0544","desc":"敷地南端中央に位置し、裏門は塀から敷地内側にやや後退し、引違戸を建てる。塀は腕木で桟瓦葺屋根を受け、土地の勾配に合わせ、高さを三段に切替える。裏門の屋根は塀と一体とし、敷地内側に葺下ろす。裏門と東側の塀は欄間で飾り、敷地背面の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013255"},{"id":"00013254","register_sub_id":"101","register_pk":"366243","name":"川原田家住宅表門及び塀","kana":"かわらだけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市昭和区南山町25-4","lat":35.142275,"lng":136.95060833,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"門 木造、瓦葺、間口2.1m 塀 木造、瓦葺、総延長26m","structure_material":"門 木造","registered":"2020.04.03(令和2.04.03)","register_no":"23 － 0543","desc":"敷地北西隅に位置し、隅切りに合わせて矩折れとする。表門は腕木門で、切妻造桟瓦葺の屋根を載せ北面して建ち、東側の袖塀に潜戸を設ける。塀は腕木で桟瓦葺屋根を受け、壁は土壁で腰の外側を竪板張、内側を杉皮張とする。近代和風住宅の表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013254"},{"id":"00013253","register_sub_id":"101","register_pk":"366242","name":"川原田家住宅主屋","kana":"かわらだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市昭和区南山町25-4他","lat":35.14205556,"lng":136.95068333,"geo_status":"db","era":"昭和12年／昭和56年・平成30年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建一部鉄筋コンクリート造地階付、瓦葺一部銅板葺、建築面積144㎡","structure_material":"木造2階建一部鉄筋コンクリート造地階付","registered":"2020.04.03(令和2.04.03)","register_no":"23 － 0542","desc":"大正期に宅地開発した住宅地に位置し、敷地中央西寄りに建つ。木造二階建、入母屋造桟瓦葺で、一階下屋は銅板葺とする。南側の庭園に面し、一、二階とも縁に沿って和室を二室並べる。玄関脇に洋室の応接間を設ける等、都市近郊住宅の昭和前期の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013253"},{"id":"00004983","register_sub_id":"101","register_pk":"105973","name":"甘強味淋住宅主屋","kana":"かんきょうみりんじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県海部郡蟹江町城4-1","lat":35.13136624,"lng":136.78988211,"geo_status":"db","era":"大正12／昭和12増改造","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積272㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"23 － 0207","desc":"社屋と工場の間にある２階建の和風住宅。東西棟の入母屋造，桟瓦葺，西面に玄関を設けた妻入で，東面に茶室を接続し，北辺が増築部である。良材を用い，洗練された書院造風を基調としつつ，２階の洋室や開放的な開口部を設け，当時の住宅の有様を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004983"},{"id":"00004984","register_sub_id":"101","register_pk":"105974","name":"甘強味淋住宅土蔵","kana":"かんきょうみりんじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県海部郡蟹江町城4-1","lat":35.13128693,"lng":136.7899829,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積42㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"23 － 0208","desc":"主屋の南東隅にあり，蔵前は主屋と接続している。土蔵造２階建，南北棟の切妻造，桟瓦葺で，１階西面に観音開扉を設け，東面の窓には庇を架ける。外壁は黒漆喰塗，頂部に鉢巻を廻す。小屋は登梁式とし，垂木を用いずに厚板を載せる。堅牢なつくりになる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004984"},{"id":"00008701","register_sub_id":"101","register_pk":"149422","name":"旧石原家住宅主屋","kana":"きゅういしはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県岡崎市六供町字杉本70","lat":34.96167636,"lng":137.16869273,"geo_status":"db","era":"安政6年(1859)／昭和40年・昭和53年改修","year":1859,"year_source":"converted","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積163㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"23 － 0338","desc":"角地に建ち、北側を正面とする。間口18ｍ奥行9.1ｍの木造つし二階建。切妻造桟瓦葺で、南・北・東面に下屋を付設。東寄りに土間、西に2列各3室を配し、西端に仏間と座敷を並べる。土間正面に大戸をたて、太格子や出格子を並べ、町家らしい構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008701"},{"id":"00008702","register_sub_id":"101","register_pk":"149423","name":"旧石原家住宅土蔵","kana":"きゅういしはらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県岡崎市六供町字杉本70","lat":34.96155707,"lng":137.1688081,"geo_status":"db","era":"安政6年(1859)／昭和53年改修","year":1859,"year_source":"converted","year_min":1859,"year_max":1859,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"23 － 0339","desc":"主屋の南に建つ。桁行5.5ｍ梁間3.6ｍ、土蔵造2階建。切妻造桟瓦葺で、西側に下屋を付設、北面に出入口を設け、深い庇をかける。西側の下屋も一連で、漆喰仕上げとし、北面以外に腰板を張る。屋敷地の東南隅に位置し、落ち着きを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008702"},{"id":"00008703","register_sub_id":"101","register_pk":"149424","name":"旧石原家住宅庭門","kana":"きゅういしはらけじゅうたくにわもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県岡崎市六供町字杉本70","lat":34.9615398,"lng":137.1687202,"geo_status":"db","era":"昭和前期／昭和53年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、杉皮葺、間口0.91m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"23 － 0340","desc":"主屋座敷南に設けられた庭園の東辺中央に位置する。間口0.91ｍの腕木門。南北棟の切妻造とし、杉皮を葺き、竹で押さえる。本柱は6角形で名栗仕上げ。楣で固め、棟木を架す。扉は両開の桟唐戸。一軒疎垂木で、杉皮を裏板に見せる。数寄屋風で軽快な庭門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008703"},{"id":"00004565","register_sub_id":"101","register_pk":"105555","name":"旧磯部家住宅裏座敷","kana":"きゅういそべけじゅうたくうらざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券72","lat":35.38165686,"lng":136.9395608,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0169","desc":"主屋裏の中庭奥に建ち北渡廊下で接続する。平屋建，入母屋造，桟瓦葺で，床，棚付８畳の主室と西に５畳半の次の間を配し，南，東矩折れに縁を廻す。柱，桁，化粧垂木等角材により質実な構えながら，軒高を低くおさえ勾配の緩い化粧軒として瀟洒な外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004565"},{"id":"00004567","register_sub_id":"101","register_pk":"105557","name":"旧磯部家住宅奥土蔵","kana":"きゅういそべけじゅうたくおくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券72","lat":35.38165326,"lng":136.93968215,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0171","desc":"敷地の東端，裏庭の奥に建つ。桁行４間，梁間２間半，土蔵造，２階建，切妻造，桟瓦葺，平入で，西面戸前に庇を付ける。戸口，窓廻りは掛子塗とし，軒，螻羽には蛇腹を廻し，庇部分も柱，桁，梁や軒裏を塗り込める。細部までつくり込んだ重厚な外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004567"},{"id":"00004566","register_sub_id":"101","register_pk":"105556","name":"旧磯部家住宅土蔵","kana":"きゅういそべけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券72","lat":35.381618,"lng":136.93965691,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0170","desc":"敷地の東裏手に独立して建つ。桁行３間，梁間２間半，土蔵造，２階建，切妻造，桟瓦葺，妻入で，西面に庇を付す。腰部は海鼠壁，戸口，窓廻りは掛子塗，軒は蛇腹を廻した本格的な構えとする。小規模ながらも細部まで丁寧な造りで，屋敷構えに欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004566"},{"id":"00004568","register_sub_id":"101","register_pk":"105558","name":"旧磯部家住宅物置","kana":"きゅういそべけじゅうたくものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券72","lat":35.38163184,"lng":136.93977971,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、瓦葺、建築面積52㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0172","desc":"東西に長い敷地の最奥に奥土蔵と並んで建つ。２階建，南北棟の切妻造，桟瓦葺で，中央に独立柱を建て，桁行に２階梁を通し大引を受ける。小屋組は和小屋。１，２階とも床を張り広い収納空間とし１階北は全面開放する。大型で屋敷背後の構えに欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004568"},{"id":"00009772","register_sub_id":"101","register_pk":"195601","name":"旧市川家住宅主屋","kana":"きゅういちかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県日進市野方町東島384","lat":35.12891209,"lng":137.03348307,"geo_status":"db","era":"明和6","year":1769,"year_source":"db","year_min":1769,"year_max":1769,"year_label":null,"structure":"木造平屋建、茅葺(鉄板仮葺)、建築面積163㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0393","desc":"尾張東部の丘陵地帯に位置する民家。右土間で床上部は前後二列に三室づつ配し、前列奥室をザシキとする。土間境柱を含めた上屋柱四本を梁で繋ぐ当地方に独特な「四つ建て」工法を基本としつつ、一部に構造的な発達過程も示す。もと庄屋の格式を伝える大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009772"},{"id":"00014389","register_sub_id":"101","register_pk":"511378","name":"旧伊東合資会社主屋","kana":"きゅういとうごうしがいしゃおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県半田市亀崎町九丁目111他","lat":34.9114,"lng":136.96269444,"geo_status":"db","era":"江戸末期／明治中期・大正2年増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階一部平屋建、瓦葺、建築面積291㎡","structure_material":"木造2階一部平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"23 - 0580","desc":"衣浦湾沿いの師崎街道に面し、醸造業を営む庄屋格旧家の主屋。二階建、切妻造平入桟瓦葺の長大な東西棟。内部は東に重厚な梁組を見せる土間、西に田の字型平面の居室に、さらに西へ続き座敷を連ねる。床構え付書院を備えた旧座敷八畳は端正で格式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014389"},{"id":"00014390","register_sub_id":"101","register_pk":"511379","name":"旧伊東合資会社新座敷","kana":"きゅういとうごうしがいしゃしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県半田市亀崎町九丁目111他","lat":34.91126111,"lng":136.96245278,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"23 - 0581","desc":"醸造業を営む旧家主屋の西に渡り廊下で繋ぐ南北棟の離れ。平屋建、寄棟造桟瓦葺、四周銅板平葺の庇を付し、北から前室四畳、次の間八畳、座敷八畳の三間続きの間取りとする。明治天皇の御休所として整備された、華美を避け洗練された意匠の数寄屋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014390"},{"id":"00014391","register_sub_id":"101","register_pk":"511380","name":"旧伊東合資会社本土蔵","kana":"きゅういとうごうしがいしゃほんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県半田市亀崎町九丁目111他","lat":34.91128333,"lng":136.96232778,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積76㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"23 - 0582","desc":"醸造業を営む旧家の家財蔵で新座敷北西、敷地西辺に建つ。土蔵造二階建、切妻造平入桟瓦葺、東正面側は腰を海鼠壁、下屋を設け掛子塗扉の戸前とする。径尺五寸牛梁、尺角無節の欅独立柱を用いる豪壮な造り。水路沿いに下見板張を見せて屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014391"},{"id":"00012562","register_sub_id":"101","register_pk":"367857","name":"旧内田佐平二家住宅隠居屋","kana":"きゅううちださへいじけじゅうたくいんきょや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県知多郡南知多町大字内海字南側55","lat":34.734612,"lng":136.873657,"geo_status":"geocoded","era":"明治前期／平成25年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積22㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0533","desc":"敷地北東隅、土蔵の東面に接続して建つ。東西棟の切妻造平入の二階建で、南面西端に出入口を設ける。内部は西が蔵前を兼ねた前室、東が釣床付の六畳の座敷で、二階は板敷の物置とする。廻船主の生活の様相を伝えるとともに伝統的な屋敷構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012562"},{"id":"00012563","register_sub_id":"101","register_pk":"367858","name":"旧内田佐平二家住宅表門及び納屋","kana":"きゅううちださへいじけじゅうたくおもてもんおよびなや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県知多郡南知多町大字内海字南側55","lat":34.734612,"lng":136.873657,"geo_status":"geocoded","era":"明治5年頃／平成23年改修","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"表門 木造、瓦葺、間口2.2m、西方潜戸付 納屋 木造平屋建、瓦葺、建築面積26㎡","structure_material":"表門 木造","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0534","desc":"敷地南面中央に開く表門と左右に連なる東・西納屋からなる。表門は桟瓦葺の薬医門、各納屋は桟瓦葺の平屋建で、各北面西端に戸口を開く。西納屋の北面西端には東面吹放しの棟が矩折れで連なり、主屋に接続する。有力船主宅の風格ある表構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012563"},{"id":"00012560","register_sub_id":"101","register_pk":"367855","name":"旧内田佐平二家住宅主屋","kana":"きゅううちださへいじけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県知多郡南知多町大字内海字南側55","lat":34.734612,"lng":136.873657,"geo_status":"geocoded","era":"明治5年頃／平成26年改修","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造2階建、瓦葺、建築面積155㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0531","desc":"内海港にある廻船主の居宅。主屋は小路に面する敷地中央に南面して建つ。切妻造桟瓦葺の二階建で、西南北三面に下屋を廻し、北面西端に角屋を出す。内部は西に土間、東に2列2室を配し、2階後方奥を客座敷とする。港町の歴史的景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012560"},{"id":"00012564","register_sub_id":"101","register_pk":"367859","name":"旧内田佐平二家住宅透塀","kana":"きゅううちださへいじけじゅうたくすきべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県知多郡南知多町大字内海字南側55","lat":34.734612,"lng":136.873657,"geo_status":"geocoded","era":"明治前期／平成25年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、延長5.6m","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0535","desc":"敷地東面後方の隣地境に建ち、隠居屋正面と主屋背面の東端をつなぐ。高さ2･4メートル、土台上に立てた柱を棟木でつなぎ、両側に出桁を通して屋根をかける。柱間は丸竹の縦格子で上部を吹寄せ襷格子とするなど軽快につくり、隠居屋前庭の添景をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012564"},{"id":"00012561","register_sub_id":"101","register_pk":"367856","name":"旧内田佐平二家住宅土蔵","kana":"きゅううちださへいじけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県知多郡南知多町大字内海字南側55","lat":34.734612,"lng":136.873657,"geo_status":"geocoded","era":"明治5年頃／平成25年改修","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0532","desc":"敷地北西隅に建つ。土蔵造二階建、東西棟の切妻造妻入で、隠居屋が接続する東面中央に扉口を開く。外壁は漆喰塗で、西面と北面に下見板を張る。内部は上下階とも板敷の一室で、和小屋を組む。街路に面した敷地角にあって港町の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012561"},{"id":"00001424","register_sub_id":"101","register_pk":"102414","name":"旧加藤家住宅北高塀","kana":"きゅうかとうけじゅうたくきたたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県北名古屋市六ッ師南屋敷704-1","lat":35.25202201,"lng":136.89255937,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、延長11m、土塀27m附属","structure_material":"木造","registered":"1999.11.18(平成11.11.18)","register_no":"23 － 0044","desc":"旧加藤家は屋敷の外周を概ね玉石積とし，腰下見板張りの塀を巡らす。北高塀は主屋北面の側庇を兼ねたもので，採光のため上部縦格子窓，下部縦板張りとする。ちなみに，旧加藤家は平成10年３月に師勝町へ寄贈され，資料館的施設としての活用が計画されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001424"},{"id":"00001420","register_sub_id":"101","register_pk":"102410","name":"旧加藤家住宅主屋","kana":"きゅうかとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県北名古屋市六ッ師南屋敷704-1","lat":35.25195704,"lng":136.89259234,"geo_status":"db","era":"明治10代","year":1877,"year_source":"converted","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階建、瓦葺、建築面積212㎡","structure_material":"木造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"23 － 0040","desc":"屋敷地の北側に建つ主屋は明治13年もしくは19年の建築と伝えられている。桟瓦葺・つし２階建で，１階は表３室・裏４室及び土間からなり，２階は収納に用いられていた。意匠や施工の質も高く，この地域の明治期地主層の洗練された住居形式をあらわしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001420"},{"id":"00001422","register_sub_id":"101","register_pk":"102412","name":"旧加藤家住宅中門","kana":"きゅうかとうけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県北名古屋市六ッ師南屋敷704-1","lat":35.25187628,"lng":136.89255038,"geo_status":"db","era":"明治10代","year":1877,"year_source":"converted","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造薬医門、間口1.0m、屋根塀7.7m附属","structure_material":"木造薬医門","registered":"1999.11.18(平成11.11.18)","register_no":"23 － 0042","desc":"主屋と長屋門の北側にある土蔵との中間に建っている。切妻造・桟瓦葺，１間１戸の薬医門で，南と北に真壁造で腰下見板張りの塀が接続する。中門・塀とも簡素なものであるが，主屋の庭を東西に区分し，屋敷内の構成要素として欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001422"},{"id":"00001423","register_sub_id":"101","register_pk":"102413","name":"旧加藤家住宅土蔵","kana":"きゅうかとうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県北名古屋市六ッ師南屋敷704-1","lat":35.25181838,"lng":136.89250272,"geo_status":"db","era":"明治10代","year":1877,"year_source":"converted","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"23 － 0043","desc":"当初は敷地西北にあったが，離れの建設に伴い，長屋門北側の地に移された。什器家財道具類を収納し，「おくら」と称された。総２階建，切妻造・桟瓦葺・平入，東面に庇を設けた形式であるが，規模が大きく，旧家の蔵にふさわしく堂々とした外観をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001423"},{"id":"00001419","register_sub_id":"101","register_pk":"102409","name":"旧加藤家住宅長屋門","kana":"きゅうかとうけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県北名古屋市六ッ師南屋敷704-1","lat":35.2517368,"lng":136.89256942,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建納屋附属、瓦葺、建築面積60㎡","structure_material":"木造平屋建納屋附属","registered":"1999.11.18(平成11.11.18)","register_no":"23 － 0039","desc":"加藤家は「大加藤」と称される旧家で，江戸期には六ツ師村の庄屋と伝えられ，約４０ｍ四方の屋敷地に，主屋や土蔵等が密集して建つ。敷地南辺に建つ長大な長屋門は，東側が門口と二室，西側がつし２階の二室の納屋からなり，旧家の風格をあらわしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001419"},{"id":"00001421","register_sub_id":"101","register_pk":"102411","name":"旧加藤家住宅離れ","kana":"きゅうかとうけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県北名古屋市六ッ師南屋敷704-1","lat":35.25193017,"lng":136.89242434,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"23 － 0041","desc":"主屋の西に建ち，渡り廊下で接続し，西面は敷地境になる。平屋建・桟瓦葺，南北棟の建物で北十畳・南八畳からなり，南に緩い起り屋根の茶室が続く。全体を軽快にまとめているが，数寄屋風の洗練された意匠に，当時の接客空間のあり方を伺うことができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001421"},{"id":"00015027","register_sub_id":"101","register_pk":"529305","name":"旧神谷家住宅主屋","kana":"きゅうかみやけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県安城市野寺町野寺33-2","lat":34.89938333,"lng":137.08580278,"geo_status":"db","era":"大正9年／昭和58年頃改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積203㎡","structure_material":"木造平屋一部2階建","registered":"2024.08.15(令和6.08.15)","register_no":"23 - 0609","desc":"史跡本證寺境内の内堀南東に南面して建つ農家の主屋。西土間上部をつし二階とした切妻造桟瓦葺。床上は六間取とし、前列西端室を仏間、後列西に角座敷を延ばし、正背面に縁を通す。前列に三室配して上段の仏間に続くなど説法に対応した西三河平野部の民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015027"},{"id":"00004559","register_sub_id":"101","register_pk":"105549","name":"旧川上貞奴邸蔵","kana":"きゅうかわかみさだやっこていくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市東区橦木町3-23","lat":35.18039624,"lng":136.91880093,"geo_status":"db","era":"大正9頃／昭和13改造／平成16移築","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造及び鉄筋コンクリート造2階建、瓦葺、建築面積22㎡","structure_material":"木造及び鉄筋コンクリート造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0162","desc":"主屋背後に独立して建つ。外壁鉄筋コンクリート造，内部木造，２階建，切妻造，桟瓦葺で，小屋組はキングポストトラスで，戸前に庇を付設する。小規模ながらたちが高く，外壁腰部を一段厚くし大きめの鉢巻を廻らした重厚な外観で，屋敷構えに欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004559"},{"id":"00004558","register_sub_id":"101","register_pk":"105548","name":"旧川上貞奴邸主屋","kana":"きゅうかわかみさだやっこていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市東区橦木町3-23","lat":35.180401,"lng":136.918671,"geo_status":"db","era":"大正9頃／昭和13改造／平成16移築","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積71㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0161","desc":"福沢桃介が川上貞奴のために建設した邸宅の旧西半部。東半洋館部の玄関，応接室，食堂等に続き，貞奴私室や茶の間など１，２階とも和室を配する。赤瓦のマンサード屋根を切り上げて２階を設け，外壁は２階をドイツ壁，１階シングル張として多彩な外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004558"},{"id":"00010607","register_sub_id":"101","register_pk":"201181","name":"旧小守家住宅主屋","kana":"きゅうこもりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券498","lat":35.383429,"lng":136.943193,"geo_status":"db","era":"大正12年／昭和34年頃・平成22年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積165㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"23－0424","desc":"犬山城下の東側、善師野往還の旧木戸前に位置する町家。二階前面の廊下は中古の造作で、当初は当地で「ばんこ二階」と呼ぶ低い中二階であったことがわかり、大正期の建築ながら、近世以来の形式を備えていた。旧城下の街並みを構成し、歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010607"},{"id":"00014836","register_sub_id":"101","register_pk":"519096","name":"旧中埜半六邸主屋","kana":"きゅうなかのはんろくていおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県半田市中村町一丁目7","lat":34.89490833,"lng":136.93468056,"geo_status":"db","era":"明治22年頃／昭和26年頃・平成27年改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造2階建、瓦葺、建築面積350㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0590","desc":"半田運河沿いに位置し、醸造業などで栄えた商家の住宅。二階建切妻造桟瓦葺を主体部とし、西に座敷棟、南に便所棟、東に台所棟を附属した大規模なもの。主体部二階は南西に２室続きの座敷を配し、二畳床を構えるなど大胆な意匠とした上質な近代和風の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014836"},{"id":"00002628","register_sub_id":"101","register_pk":"103618","name":"旧林家住宅主屋及び裏座敷","kana":"きゅうはやしけじゅうたくおもやおよびうらざしき","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県一宮市起字下町211","lat":35.306034,"lng":136.73674,"geo_status":"db","era":"大正初期／昭和初期増築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階一部平屋建、瓦葺、建築面積265㎡","structure_material":"木造2階一部平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"23 － 0058","desc":"東海道宮宿と中山道垂井を結ぶ美濃路七宿の一つ起宿の脇本陣。濃尾地震で被災した旧施設に代わって建設された現存建物は，座敷回り等に近代的な構成がみられるが，外観や細部は伝統的な大型町家の形式を踏襲し，旧宿の景観を構成する主要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002628"},{"id":"00011322","register_sub_id":"101","register_pk":"209159","name":"旧堀田廣之家住宅板塀","kana":"きゅうほったひろゆきけじゅうたくいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県津島市祢宜町68","lat":35.17683998,"lng":136.72026703,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土塀、瓦葺、延長12m","structure_material":"土塀","registered":"2016.11.29(平成28.11.29)","register_no":"23－0467","desc":"主屋西側の通り沿いで、敷地の北辺を画す塀。東寄りに潜門一所を設ける。延長一二メートル、高さ二・六メートルで、桟瓦葺の屋根を架ける。外側は腰簓子下見板張、上部土壁、内側は腰割竹張、上部土壁とする。内外の意匠を違え、敷地内外の景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011322"},{"id":"00011319","register_sub_id":"101","register_pk":"209156","name":"旧堀田廣之家住宅蔵","kana":"きゅうほったひろゆきけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県津島市祢宜町68","lat":35.176787,"lng":136.720203,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"23－0464","desc":"主屋の西側に接続して建つ。桁行八・三メートル、梁間三・八メートルの比較的小規模な二階建土蔵。主屋室内から入る内蔵であって、内部は床、壁、天井とも板張としている。屋根は切妻造、桟瓦葺で、外壁に黒色の簓子下見板張として、敷地内の景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011319"},{"id":"00011318","register_sub_id":"101","register_pk":"209155","name":"旧堀田廣之家住宅主屋","kana":"きゅうほったひろゆきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県津島市祢宜町68","lat":35.17676064,"lng":136.72037271,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積205㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"23－0463","desc":"津島神社門前の祢宜町に所在する。堀田本家出入の棟梁、杉田和平の手がけた住宅で、二階建とし、一階に生活空間を、二階に接客空間を主として配し、当時の津島における住宅の流行を良く示す。座敷飾も端正な造作になり、当地を代表する近代和風住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011318"},{"id":"00011320","register_sub_id":"101","register_pk":"209157","name":"旧堀田廣之家住宅門","kana":"きゅうほったひろゆきけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県津島市祢宜町68","lat":35.176749,"lng":136.720415,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、瓦葺、間口2.0m、袖塀付","structure_material":"木造","registered":"2016.11.29(平成28.11.29)","register_no":"23－0465","desc":"主屋東側の通り沿いに建つ。間口二・〇メートルの一間腕木門で、両開の板戸を吊る。切妻造、桟瓦葺とする。主柱の後方に、石材の控柱を添える。主屋との間には袖壁が付く。袖壁の腰は簓子下見板張として、他の建造物と意匠を統一して調和を図る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011320"},{"id":"00011321","register_sub_id":"101","register_pk":"209158","name":"旧堀田廣之家住宅煉瓦塀","kana":"きゅうほったひろゆきけじゅうたくれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県津島市祢宜町68","lat":35.17678329,"lng":136.72017481,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"煉瓦造、延長19m","structure_material":"煉瓦造","registered":"2016.11.29(平成28.11.29)","register_no":"23－0466","desc":"敷地の西辺を画す塀。延長一九メートル、高さ二・四メートル、煉瓦造で、イギリス積とする。二メートル毎に、敷地内側へ柱型を突出させて控えとし、上部には蛇腹状に煉瓦を迫り出して装飾とする。敷地の防火性能を高めるとともに、近代的な趣向を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011321"},{"id":"00010166","register_sub_id":"101","register_pk":"197999","name":"旧本多家住宅主屋","kana":"きゅうほんだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県岡崎市欠町字足延40-1","lat":34.952788,"lng":137.190375,"geo_status":"db","era":"昭和6／平成24移築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積305㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0414","desc":"木造二階建で、全体の意匠をスパニッシュでまとめつつ、車寄の尖りアーチなど、テューダー様式を加味している。また洋風外観で内部も洋間を主としながら、二階には三室続きの和座敷を持つ。洋風生活の浸透の中で和室を調和よく取入れた住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010166"},{"id":"00014845","register_sub_id":"101","register_pk":"519105","name":"久野家住宅（愛山居）主屋","kana":"くのけじゅうたく（あいざんきょ）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県東海市加木屋町愛敬83-1","lat":34.98449722,"lng":136.90614722,"geo_status":"db","era":"大正14年／昭和5年頃増築、同47年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、スレート葺、建築面積176㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0599","desc":"伊勢湾東岸の丘陵地に建つ郊外住宅。設計は西村伊作。２階建切妻造スレート葺。各階にベランダを配し１階柱間にアーチを飾る。屋根は南に妻をみせ、半円の屋根窓を付す。１階は和室、２階は洋室を中心とする。独特な外観などに西村らしい意匠がみてとれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014845"},{"id":"00014847","register_sub_id":"101","register_pk":"519107","name":"久野家住宅（愛山居）庭門","kana":"くのけじゅうたく（あいざんきょ）にわもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県東海市加木屋町愛敬83-1","lat":34.98443333,"lng":136.90618333,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"コンクリート造、面積0.9㎡","structure_material":"コンクリート造","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0601","desc":"主屋南東、南庭への出入口となる門。モルタル仕上としたコンクリート製の擬木の柱を四本立て、頂部や脚部を枝状のコンクリート製の擬木で連結して、アーチ風の門をつくる。表面のシワやコブなども丁寧に仕上げて表現し、敷地内景観のアクセントとなる庭門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014847"},{"id":"00014846","register_sub_id":"101","register_pk":"519106","name":"久野家住宅（愛山居）門柱","kana":"くのけじゅうたく（あいざんきょ）もんちゅう","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県東海市加木屋町愛敬83-2","lat":34.98445,"lng":136.90631111,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"鉄筋コンクリート造、間口2.4m","structure_material":"鉄筋コンクリート造","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0600","desc":"敷地東面に開く正門の石貼門柱。間口２・４メートル。大きさの揃った楕円形の扁平な玉石を用い、各石の頂部を斜め上方に突き出すように積上げ、全体に方形平面の柱をつくり出す。独特な意匠が特異な印象をもたらす門柱で、通りに面した景観に異彩を放つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014846"},{"id":"00004570","register_sub_id":"101","register_pk":"105560","name":"小島家住宅座敷","kana":"こじまけじゅうたくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券633","lat":35.38286351,"lng":136.94034262,"geo_status":"db","era":"弘化4","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積163㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0174","desc":"主屋南西に接続する接客施設。切妻造，桟瓦葺で，４方に下屋を廻らす。東正面北寄りに式台を備え，１５畳の広間，仏間，残月の間風の書院等をもつ。大型で，４方柾の柱，神代杉の天井板など銘木を用い，座敷飾や欄間等の細部も凝った意匠になる上質な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004570"},{"id":"00004571","register_sub_id":"101","register_pk":"105561","name":"小島家住宅南蔵","kana":"こじまけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券633","lat":35.38281279,"lng":136.94014361,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0175","desc":"敷地南方，座敷の西裏に建つ。土蔵造２階建，切妻造，桟瓦葺，平入で，東面に庇を設け戸前とする。正側面に庇付の小窓を開き，戸口，窓廻りは掛子塗，軒には蛇腹を廻した本格的なつくりとする。小規模ながら細部まで丁寧な仕事で，屋敷構えに欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004571"},{"id":"00004575","register_sub_id":"101","register_pk":"105565","name":"小島家住宅屋根塀","kana":"こじまけじゅうたくやねべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券633","lat":35.38272965,"lng":136.94010146,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、延長56m、間口1.9m門付","structure_material":"木造","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0179","desc":"敷地の東と南を矩折れに仕切る塀。座敷の式台斜め前に棟門形式，桟瓦葺の御成門，主屋及び寄付の各北に潜り戸２所を開く。上半は塗込め，下半は下見板張とし，腕木で桁を受け，桟瓦葺の屋根をかける。長大で上質なつくりで，屋敷の表構えに欠かせない建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004575"},{"id":"00004574","register_sub_id":"101","register_pk":"105564","name":"小島家住宅寄付","kana":"こじまけじゅうたくよりつき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券633","lat":35.38273354,"lng":136.94044428,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0178","desc":"茶事等に用いられた施設で，敷地南東隅に建つ。床付の７畳半座敷北に腰掛を兼ねた上り口を付けた規模で，桟瓦葺屋根は敷地側を大きく葺下ろした招き屋根の形式とし，表側の東面と北側面に庇を付ける。変化に富んだ構成をもつ赤壁塗の外観は屋敷を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004574"},{"id":"00011515","register_sub_id":"101","register_pk":"210543","name":"颯田家住宅主屋","kana":"さったけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県西尾市吉良町吉田本浜28","lat":34.79374,"lng":137.06507194,"geo_status":"db","era":"明治5年","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積214㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"23-0478","desc":"桁行一〇間、梁間四間半、寄棟造、桟瓦葺で南面する。東を土間とし、西は前後二列に六室を並べ、さらに西側に上段の仏間を付ける。土間側二室はもと広間で、天井を張らず井桁状に太い梁を二重に架けた豪壮な架構を見せるのが特徴で、居住者の格式を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011515"},{"id":"00006611","register_sub_id":"101","register_pk":"107594","name":"佐橋家住宅主屋","kana":"さはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券457","lat":35.383484,"lng":136.942276,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積170㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0271","desc":"犬山城の東南、余坂木戸跡近くの商人町に所在する。通りに南面して建つ、桁行５間梁間７間半の２階建で、切妻造平入桟瓦葺とする。２階正面の中央４間に高欄付の窓を設け、両端間を黒漆喰塗とする外観をもち、犬山城下における伝統的な町家形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006611"},{"id":"00005621","register_sub_id":"101","register_pk":"106609","name":"柴田家住宅主屋","kana":"しばたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県清須市西枇把島町辰新田65","lat":35.192986,"lng":136.85997848,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造2階建、瓦葺、建築面積144㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"23 － 0225","desc":"南面して建つ切妻造，桟瓦葺，２階建，平入で，南に下屋を設け，後方は敷地に合わせ，くの字に折れる。１階は東に通り土間，西に４室を並べ，最奥に床付の座敷を設ける。たちの低い２階は前に茶室等，奥に１５畳の座敷を配する。美濃路に面した近代町家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005621"},{"id":"00015026","register_sub_id":"101","register_pk":"529304","name":"下郷家住宅（千代倉本家）中蔵","kana":"しもざとけじゅうたく（ちよくらほんけ）なかくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区鳴海町字相原町27他","lat":35.07949444,"lng":136.95265278,"geo_status":"db","era":"明治26年","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"23 - 0608","desc":"紅葉蔵の北に落棟で接続する家財蔵。土蔵造二階建切妻造桟瓦葺、東面下屋は南二間を紅葉蔵と一連のガラス戸を建て、北は吹放ちの土間。外壁は漆喰塗で腰下見板張。小屋組は登梁形式で桁行中央は水平の鉄筋で繋ぐ。重厚な外観が紅葉蔵とともに敷地景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015026"}];
